// 產生檔：node tools/build_course_v2.js（來源 tools/content/course_v2/）。不要手改。
window.BUZZ_COURSE_V2_LESSONS = Object.assign(window.BUZZ_COURSE_V2_LESSONS || {}, {"epsilon-n-definition":{"id":"epsilon-n-definition","prerequisites":["sequence-limit","archimedean-property","negation"],"next":["epsilon-n-proofs"],"related":[],"objectives":["寫得出 $a_n\\to L$ 的 $\\varepsilon$-$N$ 定義，並說出每個量詞的角色與順序。","給定具體的 $\\varepsilon$，會解出一個（以及最小的）可用的 $N$。","會寫出「$a_n$ 不收斂到 $L$」的否定句，並用它證明 $(-1)^n$ 發散。"],"concept":[{"heading":"① 「越來越靠近」不夠精確","body":["以前說 $a_n\\to L$ 是「$n$ 越大，$a_n$ 越靠近 $L$」。但 $a_n=\\frac{1}{n}$ 也「越來越靠近」$-1$（距離一直變小），它卻不收斂到 $-1$。問題在於：越來越近，不代表近到任意程度。","精確的說法是一場挑戰：對方隨便給一個誤差 $\\varepsilon>0$（0.1、0.001、$10^{-9}$），你都要能說出一個位置 $N$，使得從第 $N$ 項開始，每一項都落在 $L\\pm\\varepsilon$ 這條帶子裡。"]},{"heading":"② 定義","body":["數列 $(a_n)$ 收斂到 $L$，寫成 $\\lim a_n=L$ 或 $a_n\\to L$，意思是：","量詞順序是重點：先有 $\\varepsilon$，才選 $N$，所以 $N$ 可以依賴 $\\varepsilon$（$\\varepsilon$ 越小，$N$ 通常越大）。$N$ 不必是最小的那個，只要「從 $N$ 開始全部都在帶子裡」就夠了。條件是對「所有 $n\\ge N$」，不是「有一些 $n$」。"],"tex":["\\forall\\varepsilon>0\\ \\exists N\\in\\mathbb{N}\\ \\forall n\\ge N:\\ |a_n-L|<\\varepsilon"]},{"heading":"③ 否定：不收斂到 $L$ 長什麼樣子","body":["照〈否定〉的規則把量詞一個一個翻過來：$a_n$ 不收斂到 $L$ 若且唯若存在一個 $\\varepsilon>0$，使得不管 $N$ 多大，$N$ 之後總有某一項 $n\\ge N$ 跑出帶子，$|a_n-L|\\ge\\varepsilon$。","人話：有一個固定的誤差，數列永遠甩不掉「偶爾跑出去」。要證明發散，就是要對所有 $L$ 都做到這件事。"],"tex":["\\exists\\varepsilon>0\\ \\forall N\\in\\mathbb{N}\\ \\exists n\\ge N:\\ |a_n-L|\\ge\\varepsilon"]}],"workedExamples":[{"title":"給 $\\varepsilon$，解出最小的 $N$","prompt":"$a_n=\\frac{2n+1}{n+3}\\to2$。$\\varepsilon=0.01$ 時，最小的 $N$ 是多少，使 $|a_n-2|<0.01$ 對所有 $n\\ge N$ 成立？","problemId":"an-en-001","steps":["先化簡距離：$a_n-2=\\frac{2n+1-2n-6}{n+3}=-\\frac{5}{n+3}$，所以 $|a_n-2|=\\frac{5}{n+3}$。","解 $\\frac{5}{n+3}<0.01$：$n+3>500$，也就是 $n>497$。","$\\frac{5}{n+3}$ 隨 $n$ 遞減，所以只要第 $N$ 項進了帶子，之後全部都在。$n=498$ 時 $\\frac{5}{501}\\approx0.00998<0.01$；$n=497$ 時 $\\frac{5}{500}=0.01$，不是嚴格小於。","最小的 $N$ 是 498。任何 $N\\ge498$ 也都符合定義。"],"answer":"$N=498$"},{"title":"收斂得很慢的數列","prompt":"$a_n=\\frac{1}{\\sqrt{n}}\\to0$。$\\varepsilon=10^{-3}$ 時最小的 $N$？","problemId":"an-en-002","steps":["$|a_n-0|=\\frac{1}{\\sqrt{n}}<10^{-3}$ 若且唯若 $\\sqrt{n}>1000$，也就是 $n>10^6$。","$\\frac{1}{\\sqrt{n}}$ 遞減，所以最小的 $N=10^6+1=1000001$；$n=10^6$ 時 $\\frac{1}{\\sqrt{n}}$ 剛好等於 $10^{-3}$，不算。","對一般的 $\\varepsilon$：取任何 $N>\\frac{1}{\\varepsilon^2}$（阿基米德性質保證存在）就行。"],"answer":"$N=1000001$"},{"title":"用否定句證明 $(-1)^n$ 發散","prompt":"證明 $a_n=(-1)^n$ 不收斂到任何實數 $L$。","steps":["反設 $a_n\\to L$。取 $\\varepsilon=1$，定義給出 $N$，使所有 $n\\ge N$ 都有 $|a_n-L|<1$。","取 $n=2N$（偶數）與 $n=2N+1$（奇數），兩者都 $\\ge N$：$|1-L|<1$ 且 $|-1-L|<1$。","三角不等式：$2=|1-(-1)|\\le|1-L|+|L-(-1)|<1+1=2$，得到 $2<2$，矛盾。","所以沒有任何 $L$ 是極限：$(-1)^n$ 發散。關鍵是 $\\varepsilon=1$ 只有兩項距離 2 的一半，一條寬 2 的帶子（開區間）裝不下距離 2 的兩個點。"],"answer":"$(-1)^n$ 發散"}],"pitfalls":["量詞順序寫反：「存在 $N$，對所有 $\\varepsilon$」會要求同一個 $N$ 對所有 $\\varepsilon$ 都行，只有從某項起恆等於 $L$ 的數列做得到。","只檢查第 $N$ 項在帶子裡，沒說明之後每一項也都在（要靠單調或一般的不等式）。","以為 $N$ 一定要取最小的。定義只要求存在；證明時取大一點、好寫的 $N$ 完全合法。","「距離越來越小」當成收斂。$\\frac{1}{n}$ 到 $-1$ 的距離也越來越小。"],"voice":"caac4a77","sections":[{"title":"越來越近不夠","beats":[{"show":["「$n$ 越大，$a_n$ 越靠近 $L$」"],"note":"以前的說法。","say":"以前說數列收斂，是 n 越大，a n 越靠近 L。這句話聽起來沒問題，其實有漏洞。","t":[0,8784]},{"show":["$a_n=\\frac{1}{n}$ 到 $-1$ 的距離一直變小"],"say":"n 分之一跟負一的距離，也是一直在變小。那它算不算越來越靠近負一？","t":[8784,16272]}],"predict":{"ask":"$\\frac{1}{n}$ 收斂到 $-1$ 嗎？","options":[{"label":"不會：距離一直變小，但永遠大於 1","correct":true},{"label":"會，因為距離一直變小","why":"距離變小不代表小到任意程度：$\\frac{1}{n}$ 到 $-1$ 的距離是 $1+\\frac{1}{n}$，永遠大於 1。"},{"label":"要看 $n$ 取多大才知道","why":"收斂說的是整個數列的走向，不是某一項；而 $\\frac{1}{n}$ 每一項到 $-1$ 的距離都大於 1。"}]}},{"title":"一場挑戰","beats":[{"show":["對方給誤差 $\\varepsilon>0$"],"note":"0.1、0.001、$10^{-9}$，隨便給。","say":"精確的說法是一場挑戰。對方隨便給一個誤差 epsilon，零點一、零點零零一，多小都可以。","t":[16272,25824]},{"show":["你說出位置 $N$"],"note":"從第 $N$ 項起，每一項都在 $L\\pm\\varepsilon$ 的帶子裡。","say":"你要能說出一個位置 N，從第 N 項開始，每一項都落在 L 上下 epsilon 這條帶子裡。","t":[25824,33432]},{"show":["$\\forall\\varepsilon>0\\ \\exists N\\ \\forall n\\ge N:|a_n-L|<\\varepsilon$"],"say":"寫成符號就是這一行：對所有 epsilon，存在 N，對所有 n 大於等於 N，距離都小於 epsilon。","t":[33432,42120]},{"show":["先有 $\\varepsilon$，才選 $N$"],"note":"$N$ 可以依賴 $\\varepsilon$；不必是最小的。","say":"順序是重點：epsilon 先給，N 後選，所以 N 可以跟著 epsilon 變。N 也不必挑最小的。","t":[42120,51024]}],"check":0},{"title":"給 $\\varepsilon$，解 $N$","beats":[{"show":["$a_n=\\frac{2n+1}{n+3}\\to2$，$\\varepsilon=0.01$"],"say":"實際玩一回合。分子二 n 加一、分母 n 加三，往二收斂。對方出零點零一。","t":[51024,60288]},{"show":["$|a_n-2|=\\frac{5}{n+3}$"],"note":"先化簡距離。","say":"先把距離化簡：通分之後，跟二的距離是 n 加三分之五。","t":[60288,66192]},{"show":["$\\frac{5}{n+3}<0.01$ ⇔ $n+3>500$ ⇔ $n>497$"],"say":"要它小於零點零一，分母要大於五百，也就是 n 大於四百九十七。","t":[66192,72624]},{"show":["$n=497$：$\\frac{5}{500}=0.01$，不算","最小的 $N=498$"],"note":"距離隨 $n$ 遞減，進了帶子就不會再出去。","say":"四百九十七剛好等於零點零一，不是嚴格小於，所以最小的 N 是四百九十八。比它大的也都可以。","t":[72624,82368]}],"check":1},{"title":"收斂得很慢","beats":[{"show":["$a_n=\\frac{1}{\\sqrt{n}}\\to0$，$\\varepsilon=10^{-3}$"],"say":"再一個：根號 n 分之一往零收斂，對方出十的負三次方。","t":[82368,88224]},{"show":["$\\sqrt{n}>1000$ ⇔ $n>10^6$"],"say":"要根號 n 大於一千，n 就得大於十的六次方。","t":[88224,92760]},{"show":["最小的 $N=10^6+1$"],"note":"$n=10^6$ 時剛好等於 $10^{-3}$，不算。","say":"等號那一項不算，所以 N 是十的六次方加一。誤差只要求千分之一，N 卻大得驚人。","t":[92760,101592]},{"show":["一般的 $\\varepsilon$：取 $N>\\frac{1}{\\varepsilon^2}$"],"note":"阿基米德性質保證存在。","say":"對任何 epsilon，取 N 大於 epsilon 平方分之一就行，這樣的自然數一定存在。","t":[101592,108504]}],"check":3},{"title":"不收斂長什麼樣","beats":[{"show":["$\\exists\\varepsilon>0\\ \\forall N\\ \\exists n\\ge N:|a_n-L|\\ge\\varepsilon$"],"say":"把定義的量詞一個一個翻過來，就是不收斂到 L。","t":[108504,113184]},{"show":["有一個固定的誤差","數列永遠甩不掉偶爾跑出去"],"say":"人話：有一個固定的誤差，不管 N 多大，後面總有某一項跑出帶子。","t":[113184,119880]},{"show":["$(-1)^n$：取 $\\varepsilon=1$"],"note":"帶子寬 2，裝不下距離 2 的兩個點 1 和 $-1$。","say":"負一的 n 次方在一和負一之間跳，兩點距離二。誤差取一，帶子寬二又是開的，裝不下兩個點。","t":[119880,129864]}],"check":2}],"checks":[{"ask":"$a_n\\to L$ 的定義，量詞順序是？","options":[{"label":"$\\forall\\varepsilon>0\\ \\exists N\\ \\forall n\\ge N$：$|a_n-L|<\\varepsilon$","correct":true},{"label":"$\\exists N\\ \\forall\\varepsilon>0\\ \\forall n\\ge N$：$|a_n-L|<\\varepsilon$","why":"你把 $N$ 放到 $\\varepsilon$ 前面，變成一個 $N$ 要應付所有 $\\varepsilon$，等於說 $n\\ge N$ 後 $a_n=L$。$N$ 必須可以依賴 $\\varepsilon$。"},{"label":"$\\forall\\varepsilon>0\\ \\exists n$：$|a_n-L|<\\varepsilon$","why":"你只要求「有某一項」進帶子。$(-1)^n$ 對 $L=1$ 也有無數項等於 1，卻不收斂；要求的是從 $N$ 起「每一項」。"}]},{"ask":"$a_n=\\frac{2n+1}{n+3}$，$\\varepsilon=0.01$。下列哪個 $N$ 符合定義？","options":[{"label":"$N=1000$","correct":true},{"label":"$N=497$","why":"$n=497$ 時 $|a_n-2|=\\frac{5}{500}=0.01$，不是嚴格小於 0.01。最小可用的是 498，比它大的都行。"},{"label":"$N=100$","why":"你可能解成 $\\frac{5}{n}<0.05$ 之類。$n=100$ 時 $\\frac{5}{103}\\approx0.0485$，遠大於 0.01。"}]},{"ask":"「$a_n$ 不收斂到 $L$」的正確寫法是？","options":[{"label":"$\\exists\\varepsilon>0\\ \\forall N\\ \\exists n\\ge N$：$|a_n-L|\\ge\\varepsilon$","correct":true},{"label":"$\\forall\\varepsilon>0\\ \\forall N\\ \\forall n\\ge N$：$|a_n-L|\\ge\\varepsilon$","why":"你把每個量詞都改成 $\\forall$。否定時 $\\forall$ 變 $\\exists$、$\\exists$ 變 $\\forall$，而且這樣寫會要求所有項都離 $L$ 很遠，太強了。"},{"label":"$\\exists\\varepsilon>0\\ \\exists N\\ \\forall n\\ge N$：$|a_n-L|\\ge\\varepsilon$","why":"$\\exists N$ 應該翻成 $\\forall N$，$\\forall n$ 應該翻成 $\\exists n$。你寫的是「最後全部在外面」，比不收斂更強。"}]},{"ask":"$a_n=\\frac{1}{\\sqrt{n}}$，$\\varepsilon=0.01$ 時最小的 $N$？","options":[{"label":"10001","correct":true},{"label":"100","why":"你解成 $\\frac{1}{n}<0.01$。這裡是 $\\frac{1}{\\sqrt{n}}<0.01$，要 $\\sqrt{n}>100$，即 $n>10000$。"},{"label":"10000","why":"$n=10000$ 時 $\\frac{1}{\\sqrt{n}}$ 剛好等於 0.01，不是嚴格小於；要從 10001 開始。"}]}],"practice":[{"id":"an-en-001","core":true},{"id":"an-en-002","core":true},{"id":"an-en-003","core":true},{"id":"an-en-004","challenge":true,"note":"挑戰：$|a_n-3|=\\frac{3n-1}{n^2+n}$，要解二次不等式，或逐項檢查。"}]},"epsilon-n-proofs":{"id":"epsilon-n-proofs","prerequisites":["epsilon-n-definition","archimedean-property"],"next":["limit-laws-proof"],"related":["direct-proof"],"objectives":["分清楚「草稿」與「證明」：草稿從 $|a_n-L|<\\varepsilon$ 倒推 $N$，證明從 $N$ 正著寫回 $|a_n-L|<\\varepsilon$。","會把 $|a_n-L|$ 放大成一個簡單的上界（例如 $\\frac{C}{n}$），用它找 $N$，而不是硬解不等式。","寫得出一份完整的 $\\varepsilon$-$N$ 證明：給定 $\\varepsilon$、選 $N$、對 $n\\ge N$ 推出結論。"],"concept":[{"heading":"① 兩張紙：草稿與正式證明","body":["$\\varepsilon$-$N$ 證明幾乎都分兩步。草稿紙上，從想要的 $|a_n-L|<\\varepsilon$ 往回推，看 $n$ 要多大才夠，得到一個 $N$ 的公式。正式證明則反過來：「給定 $\\varepsilon>0$，取 $N=$ ……。則當 $n\\ge N$ 時，$|a_n-L|\\le$ …… $<\\varepsilon$。」","讀者只看正式證明，所以草稿裡的倒推不必寫，但正式證明的每一個不等號都要站得住。這就是〈直接證明〉的結構：從假設 $n\\ge N$ 一路推到結論。"]},{"heading":"② 不用解得剛剛好：放大成好算的上界","body":["$|a_n-L|$ 常常是一個麻煩的分式，硬解 $|a_n-L|<\\varepsilon$ 要解二次不等式。更好的做法是先放大：找一個簡單的 $b_n$，使 $|a_n-L|\\le b_n$，而且 $b_n<\\varepsilon$ 很好解。只要 $b_n<\\varepsilon$，$|a_n-L|$ 就更小於 $\\varepsilon$。","放大的常用招式：分子放大（把減掉的正數丟掉）、分母縮小（把加上的正數丟掉）。例如 $\\frac{3n-1}{n^2+n}\\le\\frac{3n}{n^2}=\\frac{3}{n}$。代價是 $N$ 比最小的大一點，但定義本來就不要求最小。"]},{"heading":"③ $N$ 要是自然數","body":["草稿常得到「$n>\\frac{3}{\\varepsilon}$」。$\\frac{3}{\\varepsilon}$ 不一定是整數，所以正式證明寫「由阿基米德性質，取自然數 $N>\\frac{3}{\\varepsilon}$」。之後 $n\\ge N>\\frac{3}{\\varepsilon}$，推得 $\\frac{3}{n}<\\varepsilon$。"]}],"workedExamples":[{"title":"最基本的一題：$\\frac{1}{n}\\to0$","prompt":"用 $\\varepsilon$-$N$ 定義證明 $\\lim\\frac{1}{n}=0$。","problemId":"px-eps-003","steps":["草稿：要 $|\\frac{1}{n}-0|=\\frac{1}{n}<\\varepsilon$，只要 $n>\\frac{1}{\\varepsilon}$。","證明：給定 $\\varepsilon>0$。由阿基米德性質，取自然數 $N>\\frac{1}{\\varepsilon}$。","對任何 $n\\ge N$：$n\\ge N>\\frac{1}{\\varepsilon}>0$，所以 $\\frac{1}{n}<\\varepsilon$，也就是 $|\\frac{1}{n}-0|<\\varepsilon$。","由定義，$\\lim\\frac{1}{n}=0$。"],"answer":"得證（$N$ 取任何大於 $\\frac{1}{\\varepsilon}$ 的自然數）"},{"title":"放大成 $\\frac{3}{n}$","prompt":"證明 $\\frac{3n^2+1}{n^2+n}\\to3$，並比較 $\\varepsilon=10^{-3}$ 時放大得到的 $N$ 與最小的 $N$。","problemId":"an-en-004","steps":["草稿：$a_n-3=\\frac{3n^2+1-3n^2-3n}{n^2+n}=\\frac{1-3n}{n^2+n}$。$n\\ge1$ 時 $3n-1>0$，所以 $|a_n-3|=\\frac{3n-1}{n^2+n}$。","放大：分子 $3n-1<3n$，分母 $n^2+n>n^2$，所以 $|a_n-3|<\\frac{3n}{n^2}=\\frac{3}{n}$。","證明：給定 $\\varepsilon>0$，取自然數 $N>\\frac{3}{\\varepsilon}$。$n\\ge N$ 時 $|a_n-3|<\\frac{3}{n}\\le\\frac{3}{N}<\\varepsilon$。","$\\varepsilon=10^{-3}$：放大法要 $N>3000$，取 $N=3001$。直接檢查原式，最小可用的是 $N=2999$（$n=2998$ 時距離約 0.0010002，還不夠）。兩個都對，放大法只是多走兩步。"],"answer":"得證；$\\varepsilon=10^{-3}$ 時放大法給 $N=3001$，最小的 $N$ 是 2999"},{"title":"先有理化再放大","prompt":"證明 $\\sqrt{n+1}-\\sqrt{n}\\to0$。","steps":["草稿：乘共軛，$\\sqrt{n+1}-\\sqrt{n}=\\frac{1}{\\sqrt{n+1}+\\sqrt{n}}$。這個量是正的。","放大：$\\sqrt{n+1}>\\sqrt{n}$，所以分母 $>2\\sqrt{n}$，得 $0<\\sqrt{n+1}-\\sqrt{n}<\\frac{1}{2\\sqrt{n}}$。","要 $\\frac{1}{2\\sqrt{n}}<\\varepsilon$，只要 $n>\\frac{1}{4\\varepsilon^2}$。","證明：給定 $\\varepsilon>0$，取自然數 $N>\\frac{1}{4\\varepsilon^2}$。$n\\ge N$ 時 $|\\sqrt{n+1}-\\sqrt{n}|<\\frac{1}{2\\sqrt{n}}\\le\\frac{1}{2\\sqrt{N}}<\\varepsilon$。例如 $\\varepsilon=0.001$ 時取 $N=250001$。"],"answer":"得證（$N>\\frac{1}{4\\varepsilon^2}$）"}],"pitfalls":["把草稿當證明交出去：從 $|a_n-L|<\\varepsilon$ 推到 $n>$ ……，方向是反的，只證明了「若在帶內則 $n$ 大」。","放大時方向弄錯：分母縮小、分子放大才是放大；把分母的 $+n$ 丟掉是對的，把分子的 $-1$ 丟掉也是對的，反過來就錯。","$N$ 寫成 $\\frac{3}{\\varepsilon}$ 卻沒說它是自然數；若取 $N=\\lceil\\frac{3}{\\varepsilon}\\rceil$，$\\frac{3}{\\varepsilon}$ 剛好是整數時 $\\frac{3}{N}=\\varepsilon$，得不到嚴格的 $<\\varepsilon$，所以要取 $N>\\frac{3}{\\varepsilon}$。","$N$ 的公式裡出現 $n$。$N$ 只能依賴 $\\varepsilon$（與題目給的常數），不能依賴之後才挑的 $n$。"],"voice":"eff2d3bf","sections":[{"title":"草稿與正式證明","beats":[{"show":["草稿：從 $|a_n-L|<\\varepsilon$ 往回推"],"note":"看 $n$ 要多大才夠，得到 $N$ 的公式。","say":"epsilon N 證明要兩張紙。草稿紙上，從想要的結果往回推，看 n 要多大才夠。","t":[0,8520]},{"show":["正式：給定 $\\varepsilon>0$，取 $N=\\dots$","則 $n\\ge N$ 時 $|a_n-L|<\\varepsilon$"],"say":"正式證明反過來寫：先給定 epsilon，再取 N，然後證 n 大於等於 N 時距離小於 epsilon。","t":[8520,16776]},{"show":["草稿的倒推不必寫"],"note":"但正式證明的每個不等號都要站得住。","say":"讀的人只看正式證明。草稿怎麼想到的不用交，但正式那一張每一步都要對。","t":[16776,24720]}],"check":0},{"title":"$\\frac{1}{n}\\to0$","beats":[{"show":["草稿：$\\frac{1}{n}<\\varepsilon$ ⇔ $n>\\frac{1}{\\varepsilon}$"],"say":"最基本的一題：n 分之一趨近零。草稿上，要 n 分之一小於 epsilon，只要 n 大於 epsilon 分之一。","t":[24720,34224]},{"show":["正式證明：給定 $\\varepsilon>0$"],"say":"現在寫正式的。第一句給定 epsilon。第二句要取 N，該怎麼寫？","t":[34224,41664]}],"predict":{"ask":"第二句：取哪個 $N$？","options":[{"label":"由阿基米德性質，取自然數 $N>\\frac{1}{\\varepsilon}$","correct":true},{"label":"取 $N=\\frac{1}{\\varepsilon}$","why":"$\\frac{1}{\\varepsilon}$ 不一定是整數；而且剛好相等時只得到 $\\frac{1}{n}\\le\\varepsilon$，不是嚴格小於。"},{"label":"取 $N>\\varepsilon$","why":"$\\varepsilon$ 很小時，$N$ 也可以很小，$\\frac{1}{N}$ 根本不會小於 $\\varepsilon$。要的是 $\\frac{1}{\\varepsilon}$。"}]}},{"title":"放大成好算的","beats":[{"show":["$n\\ge N>\\frac{1}{\\varepsilon}$ ⇒ $\\frac{1}{n}<\\varepsilon$"],"say":"取好 N 之後，n 大於等於 N，又大於 epsilon 分之一，所以 n 分之一小於 epsilon，證完。","t":[41664,49848]},{"show":["$|a_n-L|\\le b_n$，而 $b_n<\\varepsilon$ 好解"],"note":"不用解得剛剛好。","say":"距離常常是麻煩的分式。不必硬解，先放大成一個簡單的上界，讓上界小於 epsilon 就好。","t":[49848,59016]},{"show":["$\\frac{3n^2+1}{n^2+n}\\to3$","$|a_n-3|=\\frac{3n-1}{n^2+n}$"],"say":"例子：分子三 n 平方加一，分母 n 平方加 n，往三收斂。跟三的距離化簡完是這個分式。","t":[59016,68688]},{"show":["分子放大、分母縮小"],"note":"把減掉的正數丟掉、把加上的正數丟掉。","say":"放大的招式：分子把減掉的一丟掉，變大；分母把加上的 n 丟掉，變小。整個分式就變大了。","t":[68688,78480]}],"check":1},{"title":"$N$ 要是自然數","beats":[{"show":["$|a_n-3|<\\frac{3n}{n^2}=\\frac{3}{n}$"],"say":"放大之後是 n 分之三，要它小於 epsilon，n 大於 epsilon 分之三就夠。","t":[78480,85200]},{"show":["取自然數 $N>\\frac{3}{\\varepsilon}$"],"note":"$\\frac{3}{\\varepsilon}$ 不一定是整數。","say":"epsilon 分之三不一定是整數，所以寫：由阿基米德性質，取一個比它大的自然數 N。","t":[85200,93240]},{"show":["$\\varepsilon=10^{-3}$：放大法 $N=3001$","最小可用的 $N=2999$"],"say":"誤差十的負三次方，放大法給三千零一，最小可用的是兩千九百九十九。兩個都對，只是多走兩步。","t":[93240,103584]},{"show":["$N$ 只能依賴 $\\varepsilon$"],"note":"不能依賴之後才挑的 $n$。","say":"還有一條：N 的公式只能用 epsilon 和題目給的常數，不能用到後來才挑的 n。","t":[103584,110952]}],"check":3},{"title":"先有理化再放大","beats":[{"show":["$\\sqrt{n+1}-\\sqrt{n}=\\frac{1}{\\sqrt{n+1}+\\sqrt{n}}$"],"note":"乘共軛，這個量是正的。","say":"根號 n 加一減根號 n，乘共軛，變成一個分子是一的分式，而且是正的。","t":[110952,118176]},{"show":["分母 $>2\\sqrt{n}$ ⇒ 距離 $<\\frac{1}{2\\sqrt{n}}$"],"say":"分母兩個根號裡，大的那個換成小的，分母變小，分式變大，上界是二倍根號 n 分之一。","t":[118176,126888]},{"show":["取自然數 $N>\\frac{1}{4\\varepsilon^2}$"],"note":"例：$\\varepsilon=0.001$ 時 $N=250001$。","say":"要這個上界小於 epsilon，n 要大於四倍 epsilon 平方分之一。取比它大的自然數就好。","t":[126888,135096]}],"check":2}],"checks":[{"ask":"要證 $a_n\\to L$，正式證明的第一句應該是？","options":[{"label":"給定 $\\varepsilon>0$。","correct":true},{"label":"設 $|a_n-L|<\\varepsilon$。","why":"這是在假設結論，是草稿倒推的起點，不能出現在正式證明裡。"},{"label":"取 $N=\\frac{1}{\\varepsilon}$。","why":"$\\varepsilon$ 還沒出現就先用它；而且 $\\frac{1}{\\varepsilon}$ 未必是自然數。要先給定 $\\varepsilon$，再選自然數 $N>\\frac{1}{\\varepsilon}$。"}]},{"ask":"$n\\ge1$ 時，下列哪個是 $\\frac{3n-1}{n^2+n}$ 的正確上界？","options":[{"label":"$\\frac{3}{n}$","correct":true},{"label":"$\\frac{3}{n^2}$","why":"你把分子 $3n-1$ 當成常數 3。$n=3$ 時原式是 $\\frac{8}{12}\\approx0.667$，比 $\\frac{3}{9}\\approx0.333$ 大，所以 $\\frac{3}{n^2}$ 不是上界。"},{"label":"$\\frac{1}{n}$","why":"$n=3$ 時 $\\frac{9-1}{12}=\\frac{2}{3}$，比 $\\frac{1}{3}$ 大。分子大約 $3n$，丟掉 3 就變成下界了。"}]},{"ask":"證明 $\\sqrt{n+1}-\\sqrt{n}\\to0$ 時，$\\varepsilon=0.01$ 可以取哪個 $N$？","options":[{"label":"$N=2501$","correct":true},{"label":"$N=101$","why":"你可能用了 $\\frac{1}{n}<\\varepsilon$。上界是 $\\frac{1}{2\\sqrt{n}}$，要 $n>\\frac{1}{4\\varepsilon^2}=2500$。"},{"label":"$N=2500$","why":"$n>\\frac{1}{4\\varepsilon^2}$ 是嚴格的，$n=2500$ 時上界 $\\frac{1}{2\\cdot50}$ 剛好等於 0.01，放大法保證不了 $<\\varepsilon$。"}]},{"ask":"下列哪個「$N$」的寫法不合法？","options":[{"label":"取 $N=n+1$","correct":true},{"label":"取自然數 $N>\\frac{5}{\\varepsilon}$","why":"這是合法的：$N$ 只依賴 $\\varepsilon$。你可能以為 $N$ 一定要是公式算出的最小值。"},{"label":"取自然數 $N>\\max(10,\\frac{1}{\\varepsilon})$","why":"這是合法的：$N$ 只依賴 $\\varepsilon$，同時滿足兩個條件時取較大的那個是常用寫法。"}]}],"practice":[{"id":"px-eps-003","core":true},{"id":"an-en-001","core":true},{"id":"an-en-004","core":true},{"id":"an-en-003"}]},"limit-laws-proof":{"id":"limit-laws-proof","prerequisites":["epsilon-n-proofs","limit-laws-direct"],"next":["monotone-convergence-proof"],"related":["epsilon-n-definition"],"objectives":["用 $\\frac{\\varepsilon}{2}$ 的分帳技巧證明和的極限定律。","說得出乘積定律為什麼需要「收斂數列有界」，並會證明這個引理。","知道定律只有一個方向：$a_n+b_n$ 收斂不代表 $a_n$、$b_n$ 各自收斂；除法要求分母的極限不是 0。"],"concept":[{"heading":"① 我們一直在用、但還沒證明的東西","body":["〈直接代入與極限定律〉裡的「和的極限等於極限的和」等規則，現在要用 $\\varepsilon$-$N$ 定義證明。設 $a_n\\to a$、$b_n\\to b$，要證 $a_n+b_n\\to a+b$、$a_nb_n\\to ab$，以及 $b\\ne0$ 時 $\\frac{a_n}{b_n}\\to\\frac{a}{b}$。"]},{"heading":"② 和：誤差分兩半","body":["三角不等式給 $|(a_n+b_n)-(a+b)|\\le|a_n-a|+|b_n-b|$。總誤差要 $<\\varepsilon$，就讓兩邊各 $<\\frac{\\varepsilon}{2}$。因為 $\\frac{\\varepsilon}{2}$ 也是正數，定義讓我們對 $(a_n)$ 拿到一個 $N_1$、對 $(b_n)$ 拿到一個 $N_2$；取 $N=\\max(N_1,N_2)$，兩個條件同時成立。","這個「先決定最後要的誤差，再分配給每一塊」的手法，之後會一再出現。"]},{"heading":"③ 乘積：需要一個「有界」","body":["$a_nb_n-ab=a_n(b_n-b)+b(a_n-a)$。第二項好控制，$b$ 是固定的數；第一項前面乘著 $a_n$，它會變。所以要先知道：收斂數列一定有界，存在 $M>0$ 使所有 $|a_n|\\le M$。有了 $M$，$|a_n(b_n-b)|\\le M|b_n-b|$，又回到分兩半的情形。","反過來不對：$(-1)^n$ 有界但不收斂。"]},{"heading":"④ 定律只有一個方向","body":["定律說：兩個都收斂 $\\Rightarrow$ 和收斂。反方向錯：$a_n=n$、$b_n=-n$ 都發散，$a_n+b_n=0$ 卻收斂。除法要 $b\\ne0$：$a_n=\\frac{1}{n}$、$b_n=\\frac{1}{n^2}$ 都 $\\to0$，$\\frac{a_n}{b_n}=n$ 發散。"]},{"heading":"證明：和與有界","body":["和：給定 $\\varepsilon>0$。取 $N_1$ 使 $n\\ge N_1$ 時 $|a_n-a|<\\frac{\\varepsilon}{2}$，取 $N_2$ 使 $n\\ge N_2$ 時 $|b_n-b|<\\frac{\\varepsilon}{2}$，令 $N=\\max(N_1,N_2)$。$n\\ge N$ 時 $|(a_n+b_n)-(a+b)|\\le|a_n-a|+|b_n-b|<\\frac{\\varepsilon}{2}+\\frac{\\varepsilon}{2}=\\varepsilon$。","有界：對 $\\varepsilon=1$ 取 $N$，使 $n\\ge N$ 時 $|a_n-a|<1$，於是 $|a_n|\\le|a_n-a|+|a|<1+|a|$。前面只有有限多項 $a_1,\\dots,a_{N-1}$。令 $M=\\max(|a_1|,\\dots,|a_{N-1}|,1+|a|)$，則所有 $n$ 都有 $|a_n|\\le M$，而且 $M\\ge1>0$。"],"collapsible":true},{"heading":"證明：乘積與倒數","body":["乘積：取上面的 $M$。給定 $\\varepsilon>0$，取 $N_1$ 使 $n\\ge N_1$ 時 $|b_n-b|<\\frac{\\varepsilon}{2M}$，取 $N_2$ 使 $n\\ge N_2$ 時 $|a_n-a|<\\frac{\\varepsilon}{2(|b|+1)}$（用 $|b|+1$ 是為了 $b=0$ 時也不會除以 0）。$n\\ge\\max(N_1,N_2)$ 時 $|a_nb_n-ab|\\le|a_n||b_n-b|+|b||a_n-a|<M\\cdot\\frac{\\varepsilon}{2M}+|b|\\cdot\\frac{\\varepsilon}{2(|b|+1)}<\\frac{\\varepsilon}{2}+\\frac{\\varepsilon}{2}=\\varepsilon$。","倒數（$b\\ne0$）：對 $|b|/2>0$ 取 $N_1$，$n\\ge N_1$ 時 $|b_n-b|<|b|/2$，所以 $|b_n|\\ge|b|-|b_n-b|>|b|/2>0$，特別是 $b_n\\ne0$。這時 $|\\frac{1}{b_n}-\\frac{1}{b}|=|b-b_n|/(|b_n||b|)<2|b_n-b|/|b|^2$。給定 $\\varepsilon>0$，再取 $N_2$ 使 $n\\ge N_2$ 時 $|b_n-b|<\\varepsilon|b|^2/2$，$n\\ge\\max(N_1,N_2)$ 時 $|\\frac{1}{b_n}-\\frac{1}{b}|<\\varepsilon$。除法 $\\frac{a_n}{b_n}=a_n\\cdot(\\frac{1}{b_n})$ 由乘積定律得到。"],"collapsible":true}],"workedExamples":[{"title":"$\\frac{\\varepsilon}{2}$ 分帳的實際數字","prompt":"$a_n=1+\\frac{1}{n}\\to1$，$b_n=2+\\frac{1}{n^2}\\to2$。$\\varepsilon=0.01$ 時，照和的證明取 $N$。","steps":["對 $(a_n)$：$|a_n-1|=\\frac{1}{n}<0.005$ 要 $n>200$，取 $N_1=201$。","對 $(b_n)$：$|b_n-2|=\\frac{1}{n^2}<0.005$ 要 $n^2>200$，$n\\ge15$ 即可（$14^2=196$ 不夠），取 $N_2=15$。","$N=\\max(201,15)=201$。檢查：$n\\ge201$ 時 $|(a_n+b_n)-3|=\\frac{1}{n}+\\frac{1}{n^2}\\le\\frac{1}{201}+\\frac{1}{201^2}\\approx0.00500<0.01$。"],"answer":"$N=201$"},{"title":"一步一步引用定律","prompt":"用極限定律求 $\\lim\\frac{3n^2+1}{n^2+n}$，並說明每一步用了哪一條。","problemId":"cx-seq-001","steps":["分子分母同除以 $n^2$：$a_n=\\frac{3+\\frac{1}{n^2}}{1+\\frac{1}{n}}$。這是對每個 $n$ 成立的代數恆等式，不涉及極限。","$\\frac{1}{n}\\to0$（上一課證過），乘積定律給 $\\frac{1}{n^2}=(\\frac{1}{n})(\\frac{1}{n})\\to0$。常數數列 $3\\to3$，和的定律給分子 $\\to3$；同理分母 $\\to1$。","分母的極限 $1\\ne0$，所以可以用除法定律：$a_n\\to\\frac{3}{1}=3$。"],"answer":"3","note":"題庫的 cx-seq-001 是同類題：$\\frac{3n^2+n}{n^2+2}$，極限也是 3。"},{"title":"定律不能倒過來用","prompt":"判斷：「若 $a_nb_n$ 收斂，且 $a_n$ 收斂，則 $b_n$ 收斂」是否成立？","steps":["找反例：$a_n=\\frac{1}{n}\\to0$，$b_n=(-1)^n$。$a_nb_n=\\frac{(-1)^n}{n}$，$|a_nb_n|=\\frac{1}{n}\\to0$，所以 $a_nb_n\\to0$。","但 $b_n=(-1)^n$ 發散（〈ε-N 定義〉證過）。所以敘述不成立。","問題出在 $a=0$：若 $a_n\\to a\\ne0$，則 $b_n=\\frac{a_nb_n}{a_n}$（$n$ 夠大時 $a_n\\ne0$）由除法定律收斂。反例必須用 $a=0$。"],"answer":"不成立；反例 $a_n=\\frac{1}{n}$、$b_n=(-1)^n$"}],"pitfalls":["和的證明兩邊都用 $\\varepsilon$，最後得到 $<2\\varepsilon$。要嘛一開始就分 $\\frac{\\varepsilon}{2}$，要嘛最後說明 $2\\varepsilon$ 也可以任意小——前者比較乾淨。","乘積證明寫成 $|a_n||b_n-b|<|a_n|\\cdot\\varepsilon$，右邊還有 $n$，不是固定的數。必須先有界 $M$。","除法沒處理 $b_n$ 可能等於 0：要先證 $n$ 夠大時 $|b_n|>|b|/2$。","把定律倒過來用：和收斂、積收斂都推不出各自收斂。"],"voice":"75529738","sections":[{"title":"和：誤差分兩半","beats":[{"show":["設 $a_n\\to a$、$b_n\\to b$"],"note":"要證和、積、商的極限定律。","say":"和的極限等於極限的和，我們一直在用，現在用 epsilon N 定義把它證出來。","t":[0,7152]},{"show":["$|(a_n+b_n)-(a+b)|\\le|a_n-a|+|b_n-b|$"],"say":"用絕對值的不等式，總誤差拆成兩塊：a n 的誤差，加上 b n 的誤差。","t":[7152,14160]},{"show":["兩邊各 $<\\frac{\\varepsilon}{2}$"],"note":"$\\frac{\\varepsilon}{2}$ 也是正數，定義照樣能用。","say":"總誤差要小於 epsilon，就讓兩塊各小於二分之 epsilon。它也是正數，兩個數列各給一個 N。","t":[14160,22968]},{"show":["$N=\\max(N_1,N_2)$"],"note":"先決定要的誤差，再分給每一塊。","say":"取兩個 N 裡比較大的那個。先決定最後要的誤差、再分配給每一塊，這個手法之後一直會用。","t":[22968,32472]}],"check":0},{"title":"分帳的實際數字","beats":[{"show":["$a_n=1+\\frac{1}{n}$，$b_n=2+\\frac{1}{n^2}$"],"note":"$\\varepsilon=0.01$，每邊分到 0.005。","say":"算一次真的。誤差零點零一，兩個數列各分到零點零零五。","t":[32472,39192]},{"show":["$\\frac{1}{n}<0.005$ ⇔ $n>200$：$N_1=201$"],"say":"第一個：n 分之一小於零點零零五，n 要大於兩百，取兩百零一。","t":[39192,45696]},{"show":["$\\frac{1}{n^2}<0.005$ ⇔ $n^2>200$"],"say":"第二個：n 平方分之一小於零點零零五，n 平方要大於兩百。n 至少要多少？","t":[45696,53904]}],"predict":{"ask":"$N_2$ 取多少？","options":[{"label":"$15$（$14^2=196$ 不夠）","correct":true},{"label":"$201$","why":"201 也行，但那是 $\\frac{1}{n}$ 的條件；$\\frac{1}{n^2}$ 收斂得快，$n^2>200$ 就夠。"},{"label":"$14$","why":"$14^2=196$，沒有大於 200，$\\frac{1}{196}$ 比 0.005 大。"}]}},{"title":"乘積要先有界","beats":[{"show":["$N=\\max(201,15)=201$"],"note":"誤差 $\\approx0.00500<0.01$。","say":"兩個取大的，N 是兩百零一。檢查一下，總誤差大約零點零零五，小於零點零一。","t":[53904,62904]},{"show":["$a_nb_n-ab=a_n(b_n-b)+b(a_n-a)$"],"say":"接著是乘積。拆成兩項：第二項前面乘的是固定的 b，好控制；第一項乘的是 a n，它會變。","t":[62904,72888]},{"show":["收斂數列一定有界：$|a_n|\\le M$"],"note":"反過來不對：$(-1)^n$ 有界但不收斂。","say":"所以要先知道收斂數列有界，用一個固定的 M 蓋住 a n。完整證明在全文。","t":[72888,80664]},{"show":["$|a_n(b_n-b)|\\le M|b_n-b|$"],"say":"有了 M，第一項又變成常數乘一個小量，回到誤差分兩半的情形。","t":[80664,87096]}],"check":1},{"title":"只有一個方向","beats":[{"show":["兩個都收斂 ⇒ 和收斂"],"note":"反方向不成立。","say":"定律只說：兩個都收斂，和就收斂。倒過來推是錯的。","t":[87096,93792]},{"show":["$a_n=n$、$b_n=-n$：都發散","$a_n+b_n=0$ 收斂"],"say":"n 和負 n 都發散，加起來卻每一項都是零，收斂。","t":[93792,99120]},{"show":["$a_n=\\frac{1}{n}$，$b_n=(-1)^n$"],"note":"$a_nb_n\\to0$，$a_n\\to0$，$b_n$ 卻發散。","say":"乘積也一樣：n 分之一乘負一的 n 次方會收斂到零，可是負一的 n 次方本身發散。","t":[99120,106920]}],"check":2},{"title":"除法要 $b\\ne0$","beats":[{"show":["$\\frac{a_n}{b_n}\\to\\frac{a}{b}$ 要 $b\\ne0$"],"note":"還要先證 $n$ 夠大時 $|b_n|>|b|/2$。","say":"除法定律多一個條件：分母的極限不是零。證明時還要先確定 b n 離零夠遠，不會除以零。","t":[106920,116424]},{"show":["$\\frac{3n^2+1}{n^2+n}=\\frac{3+\\frac{1}{n^2}}{1+\\frac{1}{n}}$"],"note":"代數恆等式，不涉及極限。","say":"用定律算一題。分子分母同除以 n 平方，這只是代數，對每個 n 都成立。","t":[116424,124416]},{"show":["分子 $\\to3$，分母 $\\to1$"],"note":"乘積定律、和的定律。","say":"n 平方分之一是 n 分之一乘自己，趨近零；用和的定律，分子趨近三、分母趨近一。","t":[124416,132984]},{"show":["分母極限 $1\\ne0$ ⇒ 極限 $=3$"],"say":"分母的極限是一，不是零，才可以用除法定律，答案是三。","t":[132984,139056]}],"check":3}],"checks":[{"ask":"證明和的定律時，為什麼取 $N=\\max(N_1,N_2)$？","options":[{"label":"要讓 $|a_n-a|<\\frac{\\varepsilon}{2}$ 與 $|b_n-b|<\\frac{\\varepsilon}{2}$ 同時成立","correct":true},{"label":"因為 $N$ 越大越好","why":"$N$ 夠用就好，不是越大越好；取 $\\max$ 的理由是同時滿足兩個條件，取 $\\min$ 會漏掉其中一個。"},{"label":"取 $\\min(N_1,N_2)$ 也可以","why":"$n\\ge\\min$ 時只保證其中一個條件成立，另一個數列可能還沒進帶子。"}]},{"ask":"乘積定律的證明裡，哪一步需要「收斂數列有界」？","options":[{"label":"控制 $|a_n||b_n-b|$，因為 $a_n$ 會隨 $n$ 變","correct":true},{"label":"控制 $|b||a_n-a|$","why":"$b$ 是固定的數，$|b|$ 本身就是常數，不需要額外的引理。"},{"label":"證明 $ab$ 存在","why":"$a$、$b$ 是實數，$ab$ 當然存在。有界引理是用來把會變的因子 $a_n$ 換成固定的 $M$。"}]},{"ask":"$a_n=n$、$b_n=-n$。下列何者正確？","options":[{"label":"$a_n+b_n$ 收斂，但不能用和的定律，因為 $a_n$、$b_n$ 都發散","correct":true},{"label":"$\\lim(a_n+b_n)=\\lim a_n+\\lim b_n=\\infty-\\infty=0$","why":"你把定律套在不收斂的數列上，又把 $\\infty$ 當數相減。定律的前提是兩個極限都是實數。"},{"label":"$a_n+b_n$ 發散，因為兩個都發散","why":"$a_n+b_n=0$ 對每個 $n$ 都成立，是常數數列，收斂到 0。定律不能倒過來推。"}]},{"ask":"$a_n=\\frac{1}{n}$，$b_n=\\frac{1}{n^2}$。$\\lim\\frac{a_n}{b_n}$ 是？","options":[{"label":"不存在（$\\frac{a_n}{b_n}=n$ 發散）","correct":true},{"label":"$\\frac{0}{0}=1$","why":"除法定律要求分母極限不是 0；這裡分母 $\\to0$，不能套。直接化簡 $\\frac{a_n}{b_n}=n$。"},{"label":"0","why":"你可能只看分子 $\\to0$。分母更快 $\\to0$，比值是 $n$，越來越大。"}]}],"practice":[{"id":"cx-seq-001","core":true},{"id":"lec-11-q1a","core":true}]},"monotone-convergence-proof":{"id":"monotone-convergence-proof","prerequisites":["monotone-convergence-sequence","sup-inf","completeness-axiom","epsilon-n-definition"],"next":["cauchy-sequence"],"related":["induction","recursive-sequence"],"objectives":["用上確界的 $\\varepsilon$ 判準證明：遞增且有上界的數列收斂到它的上確界。","對每一個前提舉出反例：不單調、無上界、以及在有理數裡會失效（缺完備性）。","處理遞迴數列：先用歸納法證有界與單調，再解極限方程，並用界排除多餘的根。"],"concept":[{"heading":"① 只往上走、又撞不破天花板","body":["一個遞增數列，如果有上界，直覺上它一定會停在某個高度附近：不能往回走，又不能無限上去。〈單調收斂定理〉在主線是當成事實用的，這一課要說清楚它到底靠什麼成立。","答案是完備性：「停下來的那個高度」就是集合 $\\{a_n\\}$ 的上確界。實數有完備性，所以這個上確界一定存在。"]},{"heading":"② 定理與證明","body":["定理：若 $(a_n)$ 遞增（$a_n\\le a_{n+1}$ 對所有 $n$）且有上界，則 $a_n$ 收斂，而且 $\\lim a_n=\\sup\\{a_n:n\\in\\mathbb{N}\\}$。遞減且有下界時，同理收斂到下確界。","證明：$S=\\{a_n\\}$ 非空、有上界，由完備性公理，$s=\\sup S$ 存在。給定 $\\varepsilon>0$。由 $\\varepsilon$ 判準，存在 $N$ 使 $a_N>s-\\varepsilon$。對所有 $n\\ge N$，遞增給 $a_N\\le a_n$，上界給 $a_n\\le s$，所以 $s-\\varepsilon<a_N\\le a_n\\le s<s+\\varepsilon$，即 $|a_n-s|<\\varepsilon$。"]},{"heading":"③ 每一個前提都拿不掉","body":["沒有上界：$a_n=n$ 遞增，但發散到 $\\infty$。","不單調：$(-1)^n$ 有界，但不收斂。","沒有完備性：在有理數裡，1, 1.4, 1.41, 1.414, …（$\\sqrt{2}$ 的小數截斷）遞增、每項都 $<2$、全是有理數，但它要收斂到的 $\\sqrt{2}$ 不是有理數。證明裡唯一用到實數特性的地方，就是「$\\sup$ 存在」。"]}],"workedExamples":[{"title":"經典遞迴：$\\sqrt{2+a_n}$","prompt":"$a_1=\\sqrt{2}$，$a_{n+1}=\\sqrt{2+a_n}$。證明數列收斂並求極限。","problemId":"lec-11-q3c","steps":["有界（歸納）：$0<a_1=\\sqrt{2}<2$。若 $0<a_n<2$，則 $a_{n+1}=\\sqrt{2+a_n}$ 滿足 $0<a_{n+1}<\\sqrt{4}=2$。所以所有 $n$ 都有 $0<a_n<2$。","遞增：兩邊都是正數，$a_{n+1}>a_n\\iff2+a_n>a_n^2\\iff(2-a_n)(1+a_n)>0$。由第一步 $0<a_n<2$，兩個因式都正，成立。","由單調收斂定理，$L=\\lim a_n$ 存在。$a_{n+1}\\to L$，而 $\\sqrt{\\cdot}$ 連續，所以 $\\sqrt{2+a_n}\\to\\sqrt{2+L}$，得 $L=\\sqrt{2+L}$。","平方：$L^2=2+L$，$L=2$ 或 $L=-1$。所有項 $\\ge\\sqrt{2}$，所以 $L\\ge\\sqrt{2}$，排除 $-1$。$L=2$。數值：1.4142, 1.8478, 1.9616, 1.9904, …"],"answer":"$\\lim a_n=2$"},{"title":"極限方程有兩個根","prompt":"$a_1=0$，$a_{n+1}=\\frac{a_n^2+3}{4}$。求 $\\lim a_n$。","problemId":"an-ca-003","steps":["有界（歸納）：$0\\le a_1<1$。若 $0\\le a_n<1$，則 $a_n^2<1$，$a_{n+1}=\\frac{a_n^2+3}{4}<1$，而且顯然 $\\ge0$。","遞增：$a_{n+1}-a_n=\\frac{a_n^2-4a_n+3}{4}=\\frac{(a_n-1)(a_n-3)}{4}$。$a_n<1$ 時兩個因式都負，乘積為正，所以 $a_{n+1}>a_n$。","單調收斂定理給 $L$ 存在；兩邊取極限（乘積與和的定律）：$L=\\frac{L^2+3}{4}$，即 $(L-1)(L-3)=0$。","所有 $a_n<1$，所以 $L\\le1$，排除 3。$L=1$。數值：0, 0.75, 0.8906, 0.9483, 0.9748, …"],"answer":"1"},{"title":"先證收斂，才能解方程","prompt":"$a_1=1$，$a_{n+1}=2a_n$。有人寫「$L=2L$，所以 $L=0$」。錯在哪？","steps":["實際上 $a_n=2^{n-1}$：1, 2, 4, 8, …，發散到 $\\infty$。","「$L=2L$」這一步假設了 $\\lim a_n$ 是一個實數 $L$，再對兩邊取極限。前提不成立時，方程的解沒有意義。","這正是單調收斂定理的用處：先證出極限存在，解極限方程才合法。這個數列遞增但沒有上界，定理不適用。"],"answer":"沒先證收斂；數列其實發散"}],"pitfalls":["沒證收斂就解極限方程（$a_1=1$、$a_{n+1}=2a_n$ 會「解」出 0）。","解出兩個根卻不說明為什麼丟掉其中一個；要用第一步證出的界。","歸納證有界時，只寫「$a_1<2$，所以全部 $<2$」，沒有寫歸納步驟 $a_n<2\\Rightarrow a_{n+1}<2$。","以為有界就收斂。$(-1)^n$ 有界但發散；單調是必要的前提。"],"voice":"96944281","sections":[{"title":"撞不破的天花板","beats":[{"show":["遞增 + 有上界"],"note":"不能往回走，又不能無限上去。","say":"一個數列只往上走，頭上又有天花板。直覺上它一定會停在某個高度附近。","t":[0,8064]},{"show":["停下來的高度 $=\\sup\\{a_n\\}$"],"note":"完備性保證這個上確界存在。","say":"停下來的那個高度，就是所有項的上確界。實數有完備性，所以它一定存在。","t":[8064,16368]},{"show":["定理：遞增、有上界 ⇒ 收斂","$\\lim a_n=\\sup\\{a_n:n\\in\\mathbb{N}\\}$"],"say":"定理：遞增而且有上界，就收斂，極限是上確界。遞減而且有下界，就收斂到下確界。","t":[16368,26112]}],"check":3},{"title":"證明的三步","beats":[{"show":["$S=\\{a_n\\}$ 非空、有上界 ⇒ $s=\\sup S$"],"note":"由完備性公理。","say":"第一步，所有項組成的集合非空、有上界，完備性公理給出上確界 s。","t":[26112,33216]},{"show":["給定 $\\varepsilon$：存在 $N$，$a_N>s-\\varepsilon$"],"note":"上確界的 $\\varepsilon$ 判準。","say":"第二步，給定 epsilon。s 往下退 epsilon 就不是上界了，所以有某一項 a N 穿過去。","t":[33216,41448]},{"show":["$n\\ge N$：$s-\\varepsilon<a_N\\le a_n\\le s$"],"note":"遞增給 $a_N\\le a_n$，上界給 $a_n\\le s$。","say":"第三步，之後每一項都不比 a N 小，又不超過 s，全部夾在帶子裡，所以收斂到 s。","t":[41448,49656]}],"check":0},{"title":"前提拿不掉","beats":[{"show":["沒有上界：$a_n=n$"],"note":"遞增，但發散。","say":"每一個前提都拿不掉。沒有上界：n 一直往上，發散。","t":[49656,55992]},{"show":["不單調：$(-1)^n$"],"note":"有界，但不收斂。","say":"不單調：負一的 n 次方有界，可是一直跳，不收斂。","t":[55992,61512]},{"show":["沒有完備性：1, 1.4, 1.41, 1.414, …"],"note":"全是有理數、每項 $<2$，要去的 $\\sqrt{2}$ 卻不是有理數。","say":"沒有完備性：根號二的小數截斷，一、一點四、一點四一，全是有理數，要去的地方卻不在有理數裡。","t":[61512,71688]}],"check":1},{"title":"經典遞迴","beats":[{"show":["$a_1=\\sqrt{2}$，$a_{n+1}=\\sqrt{2+a_n}$"],"say":"用定理處理一個遞迴數列：第一項根號二，下一項是根號二加前一項。","t":[71688,78648]},{"show":["有界：$0<a_n<2$"],"note":"歸納：$a_n<2$ ⇒ $a_{n+1}<\\sqrt{4}=2$。","say":"先用歸納法證有界：每一項都夾在零和二之間。","t":[78648,83664]},{"show":["遞增：$a_{n+1}>a_n$ ⇔ ？"],"note":"兩邊都是正數，可以平方。","say":"再證遞增。兩邊都是正的，可以平方比較。平方之後要比的是什麼？","t":[83664,91944]}],"predict":{"ask":"$a_{n+1}>a_n$ 等價於？","options":[{"label":"$2+a_n>a_n^2$，即 $(2-a_n)(1+a_n)>0$","correct":true},{"label":"$2+a_n>a_n$","why":"左邊平方是 $2+a_n$，右邊 $a_n$ 也要平方成 $a_n^2$。"},{"label":"$\\sqrt{2+a_n}>2$","why":"要比的是 $a_{n+1}$ 和 $a_n$，不是和 2 比；而且已經證過 $a_{n+1}<2$。"}]}},{"title":"先證收斂再解","beats":[{"show":["$L=\\sqrt{2+L}$ ⇒ $L=2$ 或 $-1$"],"note":"所有項 $\\ge\\sqrt{2}$，排除 $-1$。","say":"上一題兩個因式都正，所以遞增，極限 L 存在。兩邊取極限解出二或負一，項都是正的，答案二。","t":[91944,102432]},{"show":["$a_1=0$，$a_{n+1}=\\frac{a_n^2+3}{4}$"],"note":"數值：0, 0.75, 0.8906, 0.9483, …","say":"再一個：零、零點七五、零點八九零六，往上爬。可以證明每一項都小於一，而且遞增。","t":[102432,111984]},{"show":["$(L-1)(L-3)=0$"],"note":"兩個根要用界排除一個。","say":"極限方程有兩個根，一和三。解出兩個根，一定要說清楚為什麼丟掉其中一個。","t":[111984,120408]},{"show":["$a_1=1$，$a_{n+1}=2a_n$：「$L=2L$」？"],"note":"其實 1, 2, 4, 8, … 發散。","say":"最後提醒：沒先證收斂就解方程會出事。一、二、四、八一路翻倍，卻會解出零。","t":[120408,129864]}],"check":2}],"checks":[{"ask":"單調收斂定理的證明裡，哪一步用到實數的完備性？","options":[{"label":"$\\{a_n\\}$ 的上確界存在","correct":true},{"label":"$a_N\\le a_n$（$n\\ge N$）","why":"這一步只用到遞增，任何有序的數系都成立。"},{"label":"存在 $N$ 使 $a_N>s-\\varepsilon$","why":"這是上確界的 $\\varepsilon$ 判準，前提是 $s$ 已經存在；真正需要完備性的是 $s$ 存在這件事。"}]},{"ask":"下列哪個數列遞增、有上界，但在有理數裡沒有極限？","options":[{"label":"1, 1.4, 1.41, 1.414, …（$\\sqrt{2}$ 的小數截斷）","correct":true},{"label":"$1-\\frac{1}{n}$","why":"它的極限 1 是有理數，在有理數裡也收斂。"},{"label":"$(-1)^n$","why":"它不單調，而且在實數裡也不收斂；跟有理數缺完備性無關。"}]},{"ask":"$a_1=0$，$a_{n+1}=\\frac{a_n^2+3}{4}$，極限方程得 $L=1$ 或 3。為什麼不是 3？","options":[{"label":"歸納證過所有 $a_n<1$，所以 $L\\le1$","correct":true},{"label":"因為 3 比較大，極限取小的","why":"沒有「取小的」這種規則；排除根要靠數列的界。若 $a_1=4$，數列遞增到 $\\infty$，兩個根都不是極限。"},{"label":"因為數列遞增，極限一定是較小的根","why":"遞增只告訴你 $L\\ge a_1=0$，兩個根都 $\\ge0$，排除不了 3；要用上界 1。"}]},{"ask":"哪一個敘述正確？","options":[{"label":"遞減且有下界的數列收斂到它的下確界","correct":true},{"label":"有界的數列一定收斂","why":"$(-1)^n$ 有界但不收斂。你漏了單調這個前提。"},{"label":"遞增的數列一定收斂","why":"$a_n=n$ 遞增但發散。你漏了有上界這個前提。"}]}],"practice":[{"id":"lec-11-q3a","core":true},{"id":"lec-11-q3b","core":true},{"id":"lec-11-q3c","core":true},{"id":"an-ca-003","core":true},{"id":"lx-seq-001"},{"id":"cx-seq-004"},{"id":"an-sup-004","challenge":true,"note":"挑戰：$(1+\\frac{1}{n})^n$ 遞增有上界，所以上確界就是極限 $e$。"}]},"cauchy-sequence":{"id":"cauchy-sequence","prerequisites":["epsilon-n-proofs","monotone-convergence-proof","completeness-axiom"],"next":["bolzano-weierstrass"],"related":["basel-problem"],"objectives":["寫得出 Cauchy 數列的定義，說得出它跟收斂定義的差別：不需要事先知道極限。","會用 Cauchy 判準證明收斂（不知道極限值時）與證明發散（調和級數）。","知道「相鄰兩項差 $\\to0$」不夠，以及 Cauchy $\\Rightarrow$ 收斂要靠實數的完備性。"],"concept":[{"heading":"① 不知道終點，也能判斷會不會停","body":["用 $\\varepsilon$-$N$ 定義證明收斂，得先猜出極限 $L$。但很多數列（例如 $1+\\frac{1}{4}+\\frac{1}{9}+\\dots+\\frac{1}{n^2}$ 的部分和）收斂到哪裡並不好猜。Cauchy 的想法：不看項跟終點的距離，看項與項之間的距離。如果從某處開始，任何兩項都擠在一起，數列就停得下來。"]},{"heading":"② 定義","body":["$(a_n)$ 叫做 Cauchy 數列，如果：","注意 $m$、$n$ 是「任意兩個」都 $\\ge N$ 的足標，不只是相鄰的兩項。"],"tex":["\\forall\\varepsilon>0\\ \\exists N\\in\\mathbb{N}\\ \\forall m,n\\ge N:\\ |a_m-a_n|<\\varepsilon"]},{"heading":"③ 在實數裡：收斂 $\\iff$ Cauchy","body":["收斂 $\\Rightarrow$ Cauchy：都靠近 $L$ 的兩項，彼此也靠近（$\\frac{\\varepsilon}{2}$ 分帳）。","Cauchy $\\Rightarrow$ 收斂：這個方向需要完備性。在有理數裡它是錯的：1, 1.4, 1.41, 1.414, …（$\\sqrt{2}$ 的小數截斷）第 $n$ 項之後彼此相差不到 $10^{-(n-1)}$，是有理數裡的 Cauchy 數列，但在有理數裡沒有極限。所以 Cauchy 判準可以看成完備性的另一種說法。"]},{"heading":"④ 相鄰差 $\\to0$ 不夠","body":["$H_n=1+\\frac{1}{2}+\\dots+\\frac{1}{n}$ 的相鄰差 $\\frac{1}{n+1}\\to0$，但 $H_n$ 發散（範例 2）。Cauchy 要求的是任意遠的兩項都靠近。"]},{"heading":"證明：收斂 $\\Rightarrow$ Cauchy $\\Rightarrow$ 收斂","body":["收斂 $\\Rightarrow$ Cauchy：設 $a_n\\to L$。給定 $\\varepsilon>0$，取 $N$ 使 $n\\ge N$ 時 $|a_n-L|<\\frac{\\varepsilon}{2}$。則 $m,n\\ge N$ 時 $|a_m-a_n|\\le|a_m-L|+|L-a_n|<\\varepsilon$。","Cauchy $\\Rightarrow$ 有界：對 $\\varepsilon=1$ 取 $N$，$n\\ge N$ 時 $|a_n-a_N|<1$，所以 $|a_n|<|a_N|+1$；再跟前面有限多項取最大值。","Cauchy $\\Rightarrow$ 收斂：數列有界，由〈Bolzano–Weierstrass〉有子數列 $a_{n_k}\\to L$。給定 $\\varepsilon>0$，取 $N$ 使 $m,n\\ge N$ 時 $|a_m-a_n|<\\frac{\\varepsilon}{2}$；再取 $k$ 夠大，使 $n_k\\ge N$ 且 $|a_{n_k}-L|<\\frac{\\varepsilon}{2}$（$n_k$ 嚴格遞增，所以 $n_k\\ge k$，$k$ 夠大時 $n_k\\ge N$）。則 $n\\ge N$ 時 $|a_n-L|\\le|a_n-a_{n_k}|+|a_{n_k}-L|<\\varepsilon$。"],"collapsible":true}],"workedExamples":[{"title":"不知道極限也能證收斂","prompt":"$s_n=\\sum_{k=1}^{n}\\frac{1}{k^2}$。證明 $(s_n)$ 是 Cauchy 數列，並對 $\\varepsilon=0.01$ 給出 $N$。","steps":["設 $m>n$。$s_m-s_n=\\sum_{k=n+1}^{m}\\frac{1}{k^2}$。$k\\ge2$ 時 $\\frac{1}{k^2}<\\frac{1}{k(k-1)}=\\frac{1}{k-1}-\\frac{1}{k}$。","望遠鏡相消：$s_m-s_n<\\sum_{k=n+1}^{m}(\\frac{1}{k-1}-\\frac{1}{k})=\\frac{1}{n}-\\frac{1}{m}<\\frac{1}{n}$。","給定 $\\varepsilon>0$，取自然數 $N>\\frac{1}{\\varepsilon}$。$m>n\\ge N$ 時 $|s_m-s_n|<\\frac{1}{n}\\le\\frac{1}{N}<\\varepsilon$（$m=n$ 時差為 0）。所以 $(s_n)$ 是 Cauchy，因而收斂。","$\\varepsilon=0.01$：取 $N=101$。我們證了收斂，卻完全沒用到極限值（它是 $\\frac{\\pi^2}{6}$，要到〈Basel 問題〉才算得出來）。"],"answer":"是 Cauchy 數列；$\\varepsilon=0.01$ 取 $N=101$"},{"title":"調和級數不是 Cauchy","prompt":"證明 $H_n=1+\\frac{1}{2}+\\dots+\\frac{1}{n}$ 不是 Cauchy 數列，所以發散。","problemId":"an-ca-001","steps":["$H_{2n}-H_n=\\frac{1}{n+1}+\\frac{1}{n+2}+\\dots+\\frac{1}{2n}$，共 $n$ 項，每一項都 $\\ge\\frac{1}{2n}$，所以 $H_{2n}-H_n\\ge n\\cdot\\frac{1}{2n}=\\frac{1}{2}$。","Cauchy 的否定：存在 $\\varepsilon>0$，對每個 $N$ 都有 $m,n\\ge N$ 使 $|a_m-a_n|\\ge\\varepsilon$。取 $\\varepsilon=\\frac{1}{2}$；給任何 $N$，令 $n=N$、$m=2N$，就有 $|H_m-H_n|\\ge\\frac{1}{2}$。","所以 $(H_n)$ 不是 Cauchy，在實數裡不收斂。題庫的 an-ca-001 進一步算出 $H_{2n}-H_n\\to\\ln2\\approx0.693$，確實不趨近 0。"],"answer":"不是 Cauchy；$H_n$ 發散","note":"對照：相鄰差 $H_{n+1}-H_n=\\frac{1}{n+1}\\to0$，但這不夠。"},{"title":"壓縮：每一步差距至少縮成 $\\frac{4}{25}$","prompt":"$a_1=0$，$a_{n+1}=\\frac{1}{3-a_n}$。證明數列是 Cauchy 並求極限。","problemId":"an-ca-002","steps":["界（歸納）：$a_1=0\\in[0,\\frac{1}{2}]$。若 $a_n\\in[0,\\frac{1}{2}]$，則 $3-a_n\\in[\\frac{5}{2},3]$，$a_{n+1}\\in[\\frac{1}{3},\\frac{2}{5}]\\subset[0,\\frac{1}{2}]$。","差距：$a_{n+1}-a_n=\\frac{1}{3-a_n}-\\frac{1}{3-a_{n-1}}=\\frac{a_n-a_{n-1}}{(3-a_n)(3-a_{n-1})}$，分母 $\\ge(\\frac{5}{2})^2=\\frac{25}{4}$，所以 $|a_{n+1}-a_n|\\le(\\frac{4}{25})|a_n-a_{n-1}|$。","令 $q=\\frac{4}{25}$，則 $|a_{k+1}-a_k|\\le q^{k-1}|a_2-a_1|=\\frac{q^{k-1}}{3}$。$m>n$ 時 $|a_m-a_n|\\le\\sum_{k=n}^{m-1}\\frac{q^{k-1}}{3}<\\frac{q^{n-1}}{3(1-q)}$，$n\\to\\infty$ 時 $\\to0$，所以是 Cauchy，極限 $L$ 存在。","$L=\\frac{1}{3-L}\\Rightarrow L^2-3L+1=0\\Rightarrow L=\\frac{3\\pm\\sqrt{5}}{2}$。$L\\in[0,\\frac{1}{2}]$，所以 $L=\\frac{3-\\sqrt{5}}{2}\\approx0.38197$。"],"answer":"$\\frac{3-\\sqrt{5}}{2}$"}],"pitfalls":["只檢查相鄰兩項 $|a_{n+1}-a_n|\\to0$。調和級數的部分和就是反例。","定義裡寫 $\\forall n\\ge N$：$|a_n-a_N|<\\varepsilon$ 也可以（差一個 2 倍），但寫成「對某些 $m$、$n$」就錯了。","以為 Cauchy $\\Rightarrow$ 收斂在任何數系都對。在有理數裡不成立，它等價於完備性。","用 Cauchy 判準證完收斂，還誤以為「知道極限值」。判準只保證存在。"],"voice":"60a16a5b","sections":[{"title":"不知道終點","beats":[{"show":["$\\varepsilon$-$N$ 定義：先得猜出 $L$"],"note":"例如 $1+\\frac{1}{4}+\\frac{1}{9}+\\dots+\\frac{1}{n^2}$，終點不好猜。","say":"用 epsilon N 定義證收斂，得先知道極限是多少。可是很多數列，終點根本猜不出來。","t":[0,9024]},{"show":["不看項到終點的距離","看項與項之間的距離"],"say":"Cauchy 的想法：不管終點，只看項和項之間。從某處開始任何兩項都擠在一起，數列就停得下來。","t":[9024,19128]},{"show":["$\\forall\\varepsilon>0\\ \\exists N\\ \\forall m,n\\ge N:|a_m-a_n|<\\varepsilon$"],"note":"$m$、$n$ 是任意兩個，不只相鄰。","say":"寫成定義：對每個 epsilon 有一個 N，N 之後任意兩項的距離都小於 epsilon。注意，是任意兩項。","t":[19128,28728]}],"check":0},{"title":"收斂 ⇔ Cauchy","beats":[{"show":["收斂 ⇒ Cauchy"],"note":"都靠近 $L$ 的兩項，彼此也靠近。","say":"收斂的數列一定是 Cauchy：兩項都離 L 不到二分之 epsilon，彼此就差不到 epsilon。","t":[28728,35952]},{"show":["Cauchy ⇒ 收斂：要完備性"],"note":"完整證明在全文。","say":"反過來，Cauchy 推得出收斂，靠的是實數的完備性。","t":[35952,41280]},{"show":["在 $\\mathbb{Q}$ 裡：1, 1.4, 1.41, 1.414, …"],"note":"項擠在一起，要去的 $\\sqrt{2}$ 卻不在 $\\mathbb{Q}$ 裡。","say":"在有理數裡就不成立：根號二的小數截斷，項越擠越緊，但有理數裡沒有它要去的那一點。","t":[41280,49848]}],"check":2},{"title":"不知道極限也能證","beats":[{"show":["$s_n=\\sum_{k=1}^{n}\\frac{1}{k^2}$，設 $m>n$"],"say":"回到一開始的部分和。設 m 大於 n，看 s m 減 s n，也就是從 n 加一加到 m 的那一段。","t":[49848,58656]},{"show":["$\\frac{1}{k^2}<\\frac{1}{k-1}-\\frac{1}{k}$"],"note":"$k\\ge2$。","say":"每一項 k 平方分之一，放大成 k 減一分之一減 k 分之一，這樣就能望遠鏡相消。","t":[58656,66240]},{"show":["$s_m-s_n<\\frac{1}{n}-\\frac{1}{m}<\\frac{1}{n}$"],"say":"中間全部消掉，只剩 n 分之一減 m 分之一，比 n 分之一小。","t":[66240,72120]},{"show":["取 $N>\\frac{1}{\\varepsilon}$：是 Cauchy"],"note":"$\\varepsilon=0.01$ 取 $N=101$。","say":"所以 N 取比 epsilon 分之一大就行。我們證了收斂，卻完全沒用到極限值是多少。","t":[72120,80400]}],"check":3},{"title":"相鄰差不夠","beats":[{"show":["$H_n=1+\\frac{1}{2}+\\dots+\\frac{1}{n}$"],"note":"相鄰差 $\\frac{1}{n+1}\\to0$。","say":"調和數列，相鄰兩項只差 n 加一分之一，趨近零。看起來擠在一起了？","t":[80400,88272]},{"show":["$H_{2n}-H_n$：$n$ 項，每項 $\\ge\\frac{1}{2n}$"],"note":"所以 $H_{2n}-H_n\\ge\\frac{1}{2}$。","say":"隔遠一點看：從 n 跳到二 n，中間 n 項，每一項至少二 n 分之一，加起來至少二分之一。","t":[88272,97056]},{"show":["取 $\\varepsilon=\\frac{1}{2}$：不是 Cauchy"],"note":"所以 $H_n$ 發散。","say":"不管 N 多大，N 和二 N 這兩項永遠差至少二分之一。不是 Cauchy，所以發散。","t":[97056,105168]}],"check":1},{"title":"每步縮成 $\\frac{4}{25}$","beats":[{"show":["$a_1=0$，$a_{n+1}=\\frac{1}{3-a_n}$"],"note":"歸納：所有項在 $[0,\\frac{1}{2}]$。","say":"最後一個遞迴：下一項是三減前一項分之一。先用歸納法，所有項都在零到二分之一之間。","t":[105168,114648]},{"show":["$|a_{n+1}-a_n|\\le\\frac{4}{25}|a_n-a_{n-1}|$"],"note":"分母 $\\ge(\\frac{5}{2})^2=\\frac{25}{4}$。","say":"相鄰差每走一步，至少縮成二十五分之四。差距像等比數列一樣縮，加起來也趨近零，所以是 Cauchy。","t":[114648,125184]},{"show":["$L=\\frac{1}{3-L}$ ⇒ $L=\\frac{3\\pm\\sqrt{5}}{2}$"],"say":"極限存在之後才解方程：L 平方減三 L 加一等於零，兩個根。要哪一個？","t":[125184,133440]}],"predict":{"ask":"極限是哪一個根？","options":[{"label":"$\\frac{3-\\sqrt{5}}{2}\\approx0.38197$","correct":true},{"label":"$\\frac{3+\\sqrt{5}}{2}$","why":"它比 $\\frac{1}{2}$ 大，可是所有項都在 $[0,\\frac{1}{2}]$，極限也跑不出去。"},{"label":"兩個都是","why":"極限若存在就唯一；用項的界 $[0,\\frac{1}{2}]$ 排除其中一個。"}]}}],"checks":[{"ask":"Cauchy 數列的定義是？","options":[{"label":"$\\forall\\varepsilon>0\\ \\exists N\\ \\forall m,n\\ge N$：$|a_m-a_n|<\\varepsilon$","correct":true},{"label":"$\\forall\\varepsilon>0\\ \\exists N\\ \\forall n\\ge N$：$|a_{n+1}-a_n|<\\varepsilon$","why":"你只看相鄰兩項。$H_n$ 滿足這一條卻發散；定義要求任意兩項。"},{"label":"$\\exists N\\ \\forall\\varepsilon>0\\ \\forall m,n\\ge N$：$|a_m-a_n|<\\varepsilon$","why":"$N$ 放到 $\\varepsilon$ 前面，會逼出 $N$ 之後全部相等。$N$ 要能依賴 $\\varepsilon$。"}]},{"ask":"為什麼說 $H_n$ 不是 Cauchy？","options":[{"label":"對任何 $N$，$H_{2N}-H_N\\ge\\frac{1}{2}$","correct":true},{"label":"因為 $H_{n+1}-H_n$ 不趨近 0","why":"$H_{n+1}-H_n=\\frac{1}{n+1}$ 其實趨近 0。毛病出在相隔很遠的兩項。"},{"label":"因為 $H_n$ 沒有極限值的公式","why":"沒有公式不代表發散（$\\sum\\frac{1}{k^2}$ 的部分和也一樣是靠 Cauchy 證收斂）。要用 $\\varepsilon=\\frac{1}{2}$ 證出否定句。"}]},{"ask":"1, 1.4, 1.41, 1.414, … 在有理數 $\\mathbb{Q}$ 裡是？","options":[{"label":"Cauchy 數列，但在 $\\mathbb{Q}$ 裡不收斂","correct":true},{"label":"收斂到 $\\sqrt{2}$，所以在 $\\mathbb{Q}$ 裡收斂","why":"$\\sqrt{2}$ 不是有理數。在 $\\mathbb{Q}$ 裡談收斂，極限必須在 $\\mathbb{Q}$ 裡。"},{"label":"不是 Cauchy 數列，因為它不收斂","why":"第 $n$ 項之後任兩項相差 $<10^{-(n-1)}$，滿足 Cauchy 定義。缺的是 $\\mathbb{Q}$ 的完備性。"}]},{"ask":"$s_n=\\sum_{k\\le n}\\frac{1}{k^2}$，用 $|s_m-s_n|<\\frac{1}{n}$（$m>n$）。$\\varepsilon=0.001$ 時可取哪個 $N$？","options":[{"label":"1001","correct":true},{"label":"32","why":"你可能解成 $\\frac{1}{n^2}<0.001$。我們得到的上界是 $\\frac{1}{n}$，要 $n>1000$。"},{"label":"1000 以下任何數都行，因為級數收斂","why":"收斂只保證某個 $N$ 存在，不代表小的 $N$ 就夠；這裡的估計需要 $N>\\frac{1}{\\varepsilon}=1000$。"}]}],"practice":[{"id":"an-ca-001","core":true},{"id":"an-ca-002","core":true},{"id":"an-ca-003"},{"id":"lec-12-q4a","challenge":true,"note":"挑戰：白話證明 $H_{2^k}\\ge1+\\frac{k}{2}$，是同一個「每段至少 $\\frac{1}{2}$」的估計。"}]},"bolzano-weierstrass":{"id":"bolzano-weierstrass","prerequisites":["monotone-convergence-proof","cauchy-sequence"],"next":["limsup-liminf"],"related":[],"objectives":["寫得出子數列的定義（足標 $n_1<n_2<\\dots$ 嚴格遞增），知道收斂數列的每個子數列收斂到同一個極限。","敘述 Bolzano–Weierstrass 定理：有界數列必有收斂的子數列；說得出它不告訴你是哪一個。","看懂二分法證明，並用「兩個子數列極限不同」證明數列發散。"],"concept":[{"heading":"① 有界的數列，總有一部分會聚起來","body":["$(-1)^n$ 不收斂，但只看偶數項，它是 1, 1, 1, …，收斂到 1。把無限多個點塞進一個有限長的區間，它們一定會在某處擠成一團。Bolzano–Weierstrass 定理把這個直覺說精確。"]},{"heading":"② 子數列","body":["從 $(a_n)$ 裡按原本的順序挑出無限多項：選自然數 $n_1<n_2<n_3<\\dots$，得到子數列 $(a_{n_k})_k$。足標嚴格遞增是重點：不能往回挑，也不能重複挑同一項。由歸納法可得 $n_k\\ge k$。","若 $a_n\\to L$，則每個子數列也 $\\to L$：給定 $\\varepsilon$，取 $N$ 使 $n\\ge N$ 時 $|a_n-L|<\\varepsilon$；$k\\ge N$ 時 $n_k\\ge k\\ge N$，所以 $|a_{n_k}-L|<\\varepsilon$。","反過來用：如果找得到兩個子數列收斂到不同的值，原數列一定發散。"]},{"heading":"③ 定理","body":["Bolzano–Weierstrass 定理：$\\mathbb{R}$ 中每一個有界數列都有收斂的子數列。","有界這個前提拿不掉：$a_n=n$ 的任何子數列都滿足 $a_{n_k}=n_k\\ge k$，發散到 $\\infty$。但它是充分不是必要：0, 2, 0, 4, 0, 6, … 無界，卻有收斂的子數列 0, 0, 0, …。","定理只保證存在，不告訴你極限是多少，也不告訴你挑哪些項；$\\sin n$ 有收斂子數列，但很難具體寫出來。"]},{"heading":"證明：二分法","body":["設 $|a_n|\\le M$ 對所有 $n$。令 $I_0=[-M,M]$，它含有「無限多個足標 $n$ 的 $a_n$」。若 $I_k$ 有這個性質，把它切成左右兩個閉的半區間；兩半合起來含無限多個足標，所以至少一半也含無限多個，取它為 $I_{k+1}$（兩半都行就取右半）。$I_k$ 的長度是 $\\frac{2M}{2^k}$。","挑足標：取 $n_1$ 使 $a_{n_1}\\in I_1$。有了 $n_k$ 之後，$I_{k+1}$ 含無限多個足標，所以可取 $n_{k+1}>n_k$ 使 $a_{n_{k+1}}\\in I_{k+1}$。","找極限：寫 $I_k=[l_k,r_k]$。區間一層套一層，所以 $l_k$ 遞增，而且 $l_k\\le M$。由〈單調收斂定理（嚴格版）〉，$l_k\\to L$。$a_{n_k}$ 與 $l_k$ 都在 $I_k$ 裡，所以 $|a_{n_k}-L|\\le|a_{n_k}-l_k|+|l_k-L|\\le\\frac{2M}{2^k}+|l_k-L|\\to0$。這裡用到了完備性（經由單調收斂定理）。"],"collapsible":true}],"workedExamples":[{"title":"兩個子數列，兩個極限","prompt":"$a_n=(-1)^n(1+\\frac{1}{n})$。找出兩個收斂到不同值的子數列，並說明 $(a_n)$ 發散。","steps":["$|a_n|=1+\\frac{1}{n}\\le2$，數列有界，定理保證至少有一個收斂子數列。","偶數項 $n_k=2k$：$a_{2k}=1+\\frac{1}{2k}\\to1$。","奇數項 $n_k=2k-1$：$a_{2k-1}=-(1+\\frac{1}{2k-1})\\to-1$。","若 $(a_n)$ 收斂到 $L$，每個子數列都要 $\\to L$，則 $1=L=-1$，矛盾。所以 $(a_n)$ 發散。"],"answer":"偶數項 $\\to1$，奇數項 $\\to-1$；數列發散"},{"title":"把二分法實際跑一次","prompt":"對 $a_n=(-1)^n(1+\\frac{1}{n})$、$M=2$ 跑證明裡的二分法前四步。","steps":["$I_0=[-2,2]$。左半 $[-2,0]$ 含所有奇數項，右半 $[0,2]$ 含所有偶數項，兩半都含無限多項，照規則取右半：$I_1=[0,2]$。","$[0,1]$ 不含任何項（奇數項是負的，偶數項都 $>1$）；$[1,2]$ 含所有偶數項。$I_2=[1,2]$。","$[1.5,2]$ 只含 $a_2=1.5$ 一項；$[1,1.5]$ 含所有偶數項。$I_3=[1,1.5]$。","$k\\ge2$ 時 $a_{2k}=1+\\frac{1}{2k}\\le1.25$，所以 $[1,1.25]$ 含無限多項：$I_4=[1,1.25]$。區間長度 4, 2, 1, 0.5, 0.25 減半，收向 1——正是偶數子數列的極限。"],"answer":"$I_1=[0,2]$、$I_2=[1,2]$、$I_3=[1,1.5]$、$I_4=[1,1.25]$，收向 1"},{"title":"有界是充分條件，不是必要條件","prompt":"$b_n=\\frac{n(1+(-1)^n)}{2}$，即 0, 2, 0, 4, 0, 6, …。它有沒有收斂的子數列？這跟定理矛盾嗎？","steps":["奇數項：$b_n=n\\cdot\\frac{0}{2}=0$。偶數項：$b_n=n\\cdot\\frac{2}{2}=n$。","子數列 $b_1,b_3,b_5,\\dots=0,0,0,\\dots$ 收斂到 0。","$b_n$ 無界（偶數項 $=n$），定理不適用，但定理也沒說無界的數列一定沒有收斂子數列。不矛盾：定理是「有界 $\\Rightarrow$ 有收斂子數列」，不是「若且唯若」。"],"answer":"有（奇數項全為 0）；不矛盾"}],"pitfalls":["子數列的足標可以重複或往回挑。不行，必須 $n_1<n_2<\\dots$。","以為定理說「有界數列收斂」。它只保證某個子數列收斂；$(-1)^n$ 本身發散。","以為收斂子數列的極限是唯一的。$(-1)^n(1+\\frac{1}{n})$ 就有兩個不同的子數列極限。","二分法選「含有無限多個點的那一半」寫成「含有點的那一半」。只含有限多項的那一半挑不出無限長的子數列。"],"voice":"0e420d1d","sections":[{"title":"挑出一部分","beats":[{"show":["$(-1)^n$ 不收斂","偶數項：1, 1, 1, … 收斂到 1"],"say":"負一的 n 次方不收斂，但只看偶數項，每一項都是一，收斂到一。","t":[0,6624]},{"show":["無限多個點塞進有限長的區間"],"note":"一定會在某處擠成一團。","say":"把無限多個點塞進一段有限長的區間，它們一定會在某個地方擠成一團。","t":[6624,13296]},{"show":["子數列：$n_1<n_2<n_3<\\dots$"],"note":"照原本順序挑，不能往回、不能重複。","say":"照原本的順序挑出無限多項，叫子數列。足標要嚴格遞增：不能往回挑，也不能重複挑同一項。","t":[13296,23352]},{"show":["$a_n\\to L$ ⇒ 每個子數列 $\\to L$"],"note":"因為 $n_k\\ge k$。","say":"原數列收斂到 L，每一個子數列也都收斂到 L。反過來，兩個子數列去不同的地方，原數列就發散。","t":[23352,33672]}],"check":1},{"title":"定理","beats":[{"show":["$\\mathbb{R}$ 中有界數列","必有收斂的子數列"],"say":"Bolzano–Weierstrass 定理：實數裡每一個有界數列，都挑得出一個收斂的子數列。","t":[33672,40896]},{"show":["有界拿不掉：$a_n=n$"],"note":"任何子數列 $n_k\\ge k$，都發散。","say":"有界這個前提拿不掉：n 這個數列，不管怎麼挑，都往無限大跑。","t":[40896,47400]},{"show":["但不是必要：0, 2, 0, 4, 0, 6, …"],"note":"無界，卻有收斂的子數列 0, 0, 0, …","say":"可是有界只是充分條件。零、二、零、四這個數列無界，奇數項全是零，照樣有收斂的子數列。","t":[47400,58032]},{"show":["只保證存在"],"note":"不告訴你極限，也不告訴你挑哪些項。","say":"定理只說存在，不告訴你極限是多少、該挑哪幾項。","t":[58032,63576]}],"check":0},{"title":"兩個極限","beats":[{"show":["$a_n=(-1)^n(1+\\frac{1}{n})$"],"note":"$|a_n|\\le2$，有界。","say":"看一個例子：正負交錯，大小是一加 n 分之一。絕對值不超過二，有界。","t":[63576,71592]},{"show":["偶數項 $a_{2k}=1+\\frac{1}{2k}\\to1$"],"say":"偶數項是正的，一加二 k 分之一，收斂到一。","t":[71592,76536]},{"show":["奇數項 $a_{2k-1}\\to-1$"],"say":"奇數項是負的，收斂到負一。","t":[76536,80112]},{"show":["收斂的話 $1=L=-1$：矛盾"],"note":"所以 $(a_n)$ 發散。","say":"如果原數列收斂到 L，兩個子數列都得去 L，一等於負一，矛盾。所以它發散。","t":[80112,88752]}],"check":2},{"title":"二分法","beats":[{"show":["$|a_n|\\le M$：從 $[-M,M]$ 開始"],"note":"每次切兩半，留含無限多項的那一半。","say":"定理怎麼證？二分法：從整個區間開始，切成兩半，留下含有無限多項的那一半，一直切下去。","t":[88752,98856]},{"show":["$I_0=[-2,2]$ → $I_1=[0,2]$"],"note":"兩半都含無限多項，照規則取右半。","say":"拿剛才的數列跑一次，M 是二。兩半都有無限多項，規則是取右半，留下零到二。","t":[98856,107832]},{"show":["$[0,2]$ 切成 $[0,1]$ 與 $[1,2]$"],"say":"再切一次，零到一和一到二。下一層該留哪一半？","t":[107832,113808]}],"predict":{"ask":"$I_2$ 是哪一半？","options":[{"label":"$[1,2]$：含所有偶數項","correct":true},{"label":"$[0,1]$","why":"奇數項是負的，偶數項都 $>1$，$[0,1]$ 一項都沒有。"},{"label":"哪一半都可以","why":"要留含無限多項的那一半；只含有限多項的挑不出無限長的子數列。"}]}},{"title":"端點收斂","beats":[{"show":["$I_3=[1,1.5]$，$I_4=[1,1.25]$"],"note":"長度 4, 2, 1, 0.5, 0.25 減半，收向 1。","say":"繼續切，一到一點五，一到一點二五。區間一直減半，收向一，正是偶數子數列的極限。","t":[113808,123288]},{"show":["每層挑一項：$n_{k+1}>n_k$，$a_{n_{k+1}}\\in I_{k+1}$"],"say":"每一層挑一項，足標比上一項大。這一層有無限多項，一定挑得到。","t":[123288,130824]},{"show":["左端點 $l_k$ 遞增、$\\le M$"],"note":"區間一層套一層。","say":"區間一層套一層，左端點只會往右移，又不超過 M。它為什麼會收斂？","t":[130824,138600]}],"check":3}],"checks":[{"ask":"Bolzano–Weierstrass 定理說的是？","options":[{"label":"有界數列必有收斂的子數列","correct":true},{"label":"有界數列必收斂","why":"$(-1)^n$ 有界但發散。定理只保證「某個子數列」收斂。"},{"label":"有收斂子數列的數列必有界","why":"這是反方向，而且是錯的：0, 2, 0, 4, … 無界，卻有收斂子數列 0, 0, …。"}]},{"ask":"下列哪一個是 $(a_n)$ 的子數列？","options":[{"label":"$a_2,a_5,a_9,a_{14},\\dots$（足標嚴格遞增）","correct":true},{"label":"$a_1,a_1,a_2,a_2,a_3,a_3,\\dots$","why":"重複挑同一項，足標不是嚴格遞增。"},{"label":"$a_3,a_1,a_4,a_2,\\dots$","why":"足標往回走（3 之後挑 1），子數列必須保持原本的順序。"}]},{"ask":"要證 $(a_n)$ 發散，下列哪一招可以？","options":[{"label":"找兩個子數列，極限不同","correct":true},{"label":"證明數列有界","why":"有界推不出發散：收斂數列也都有界。你可能把定理的「有界 $\\Rightarrow$ 有收斂子數列」記成跟發散有關。"},{"label":"找一個收斂的子數列","why":"收斂數列的子數列也收斂，找到一個收斂子數列推不出原數列發散。"}]},{"ask":"二分法證明裡，區間端點 $l_k$ 收斂靠的是什麼？","options":[{"label":"$l_k$ 遞增且有上界 $M$，由單調收斂定理（完備性）","correct":true},{"label":"區間長度 $\\frac{2M}{2^k}\\to0$","why":"長度 $\\to0$ 只說明 $l_k$ 與 $r_k$ 越來越近，不保證它們有極限；在有理數裡這種套疊區間可以收向一個不存在的點。"},{"label":"$a_{n_k}$ 收斂，所以 $l_k$ 也收斂","why":"這是倒果為因：證明正是要先得到 $l_k$ 的極限 $L$，再推出 $a_{n_k}\\to L$。"}]}],"practice":[{"id":"an-ls-001","core":true,"note":"分別看偶數項與奇數項的極限，再取大的那一個。"},{"id":"an-ls-002","core":true,"note":"同上，取小的那一個。"}]},"limsup-liminf":{"id":"limsup-liminf","prerequisites":["bolzano-weierstrass","sup-inf","monotone-convergence-proof"],"next":["epsilon-delta-definition"],"related":["root-test","radius-of-convergence"],"objectives":["用尾巴的上確界 $s_n=\\sup\\{a_k:k\\ge n\\}$ 定義 $\\limsup$，說得出為什麼這個極限一定存在（有界時）。","分清楚 $\\sup S$ 與 $\\limsup$：前者看所有項，後者只看「最後」的行為。","會用「最大／最小的子數列極限」算 $\\limsup$、$\\liminf$，並用 $\\limsup=\\liminf$ 判斷收斂。"],"concept":[{"heading":"① 不收斂的數列，也有「最後的天花板」","body":["$(-1)^n+\\frac{1}{n}$ 不收斂，但它最後在 1 與 $-1$ 附近來回跳。上極限 $\\limsup$ 就是在描述「最後上緣在哪裡」，下極限 $\\liminf$ 描述「最後下緣在哪裡」。","它跟 $\\sup$ 不一樣：這個數列的 $\\sup$ 是 $a_2=\\frac{3}{2}$，但那只是前面某一項偶然很大；往後看，數列再也不會超過 1 太多。"]},{"heading":"② 定義：尾巴的上確界，再取極限","body":["設 $(a_n)$ 有界。對每個 $n$，令 $s_n=\\sup\\{a_k:k\\ge n\\}$（第 $n$ 項以後的上確界）、$t_n=\\inf\\{a_k:k\\ge n\\}$。","$n$ 變大時取 $\\sup$ 的集合變小，所以 $s_n$ 遞減，而且有下界；由單調收斂定理，$s_n$ 收斂。同理 $t_n$ 遞增有上界。定義","若數列沒有上界，約定 $\\limsup a_n=+\\infty$；沒有下界時 $\\liminf a_n=-\\infty$。"],"tex":["\\limsup_{n\\to\\infty}a_n=\\lim_{n\\to\\infty}\\,\\sup_{k\\ge n}a_k,\\qquad \\liminf_{n\\to\\infty}a_n=\\lim_{n\\to\\infty}\\,\\inf_{k\\ge n}a_k"]},{"heading":"③ 實際在用的兩個事實","body":["(a) 有界時，$\\limsup$ 是所有子數列極限中最大的那一個，$\\liminf$ 是最小的那一個。所以實際計算常常是：找出各個子數列的極限，取最大與最小。","(b) $\\liminf a_n\\le\\limsup a_n$，而且 $a_n$ 收斂若且唯若兩者相等（都是實數），這時共同的值就是極限。"]},{"heading":"證明：$\\limsup$ 是最大的子數列極限","body":["記 $L=\\lim s_n$。上界：若 $a_{n_k}\\to\\ell$，則 $a_{n_k}\\le s_{n_k}$（$a_{n_k}$ 屬於第 $n_k$ 項以後的那個集合）。$s_{n_k}$ 是 $(s_n)$ 的子數列，$\\to L$；取極限得 $\\ell\\le L$。","取得到：由 $\\varepsilon$ 判準取 $n_1$ 使 $a_{n_1}>s_1-1$。有了 $n_k$，看 $s_{n_k+1}=\\sup\\{a_j:j>n_k\\}$，取 $n_{k+1}>n_k$ 使 $a_{n_{k+1}}>s_{n_k+1}-\\frac{1}{k+1}$。又 $a_{n_{k+1}}\\le s_{n_k+1}$。夾在中間的兩端都 $\\to L$（$s_{n_k+1}$ 是 $(s_n)$ 的子數列），由夾擠 $a_{n_k}\\to L$。","(b) 的證明：若 $\\limsup=\\liminf=L$，由 $t_n\\le a_n\\le s_n$ 夾擠得 $a_n\\to L$。反之若 $a_n\\to L$，每個子數列都 $\\to L$，最大與最小的子數列極限都是 $L$。"],"collapsible":true}],"workedExamples":[{"title":"上確界取不到，但每條尾巴都一樣","prompt":"求 $\\limsup$ 與 $\\liminf$：$a_n=(-1)^n\\frac{n}{n+1}$。","problemId":"an-ls-001","steps":["偶數項 $\\frac{2k}{2k+1}<1$，遞增 $\\to1$；奇數項 $-\\frac{2k-1}{2k}$，遞減 $\\to-1$。","尾巴的上確界：任何 $n$ 之後都還有偶數項，而偶數項任意靠近 1、但都小於 1，所以 $s_n=1$ 對每個 $n$ 都成立。$\\limsup=1$。","同理 $t_n=-1$，$\\liminf=-1$。兩者不相等，數列發散。"],"answer":"$\\limsup=1$，$\\liminf=-1$"},{"title":"$\\sup$ 與 $\\limsup$ 不一樣","prompt":"$a_n=(-1)^n+\\frac{1}{n}$。求 $\\sup\\{a_n\\}$、$\\limsup a_n$、$\\liminf a_n$。","problemId":"an-ls-002","steps":["前幾項：$0,\\frac{3}{2},-\\frac{2}{3},\\frac{5}{4},-\\frac{4}{5},\\frac{7}{6},\\dots$。偶數項 $1+\\frac{1}{n}$ 遞減，奇數項 $-1+\\frac{1}{n}$ 也遞減。","$\\sup$：偶數項最大的是 $a_2=\\frac{3}{2}$，奇數項都 $\\le0$，所以 $\\sup=\\frac{3}{2}$。","子數列極限：偶數項 $1+\\frac{1}{2k}\\to1$，奇數項 $-1+\\frac{1}{2k-1}\\to-1$。每個子數列要嘛有無限多個偶數項、要嘛有無限多個奇數項，所以子數列極限只可能是 1 或 $-1$。$\\limsup=1$，$\\liminf=-1$。","$\\sup=\\frac{3}{2}>\\limsup=1$：$\\sup$ 被 $a_2$ 這一項拉高，$\\limsup$ 不在乎前面有限多項。"],"answer":"$\\sup=\\frac{3}{2}$，$\\limsup=1$，$\\liminf=-1$"},{"title":"$\\limsup$ 的用處：根值判別","prompt":"冪級數 $\\sum a_nx^n$，$a_n=2^n$（$n$ 偶數）、$3^n$（$n$ 奇數）。求收斂半徑。","problemId":"an-ls-004","steps":["$|a_n|^{1/n}$ 在 $n$ 偶數時是 2、$n$ 奇數時是 3，沒有極限，所以「$\\lim|a_n|^{1/n}$」用不了。","收斂半徑的完整公式是 $\\frac{1}{R}=\\limsup|a_n|^{1/n}$。子數列極限只有 2 與 3，$\\limsup=3$。","$R=\\frac{1}{3}$。比值 $\\frac{a_{n+1}}{a_n}$ 在 $n$ 偶數時是 $\\frac{3^{n+1}}{2^n}$（$\\to\\infty$）、$n$ 奇數時是 $\\frac{2^{n+1}}{3^n}$（$\\to0$），比值判別完全失效。"],"answer":"$R=\\frac{1}{3}$"}],"pitfalls":["把 $\\limsup$ 算成 $\\sup$。前面有限多項可以把 $\\sup$ 拉高，$\\limsup$ 完全不受影響。","以為 $\\limsup$ 一定是數列裡的某一項。$(-1)^n\\frac{n}{n+1}$ 的 $\\limsup=1$，沒有任何一項等於 1。","$s_n$ 寫成 $\\sup\\{a_n,a_{n+1}\\}$（只看兩項）。$s_n$ 是整條尾巴的上確界。","$\\limsup=\\liminf$ 時忘了要求是實數：$a_n=n$ 的兩者都是 $+\\infty$，但數列不收斂（發散到 $\\infty$）。"],"voice":"6e06b4e1","sections":[{"title":"最後的上緣","beats":[{"show":["$(-1)^n+\\frac{1}{n}$：不收斂"],"note":"最後在 1 與 $-1$ 附近來回跳。","say":"這個數列不收斂，但它最後就在一和負一附近來回跳。上緣跟下緣，最後在哪裡？","t":[0,8904]},{"show":["$s_n=\\sup\\{a_k:k\\ge n\\}$"],"note":"第 $n$ 項以後那條尾巴的上確界。","say":"辦法是看尾巴：把第 n 項以後的所有項拿出來，取上確界，叫 s n。","t":[8904,15840]},{"show":["$\\limsup a_n=\\lim s_n$","$\\liminf a_n=\\lim t_n$"],"note":"$t_n$：尾巴的下確界。","say":"n 越來越大，看 s n 的極限，就是上極限；尾巴的下確界取極限，就是下極限。","t":[15840,23832]},{"show":["$s_n$ 遞減、有下界 ⇒ 收斂"],"note":"沒有上界時約定 $\\limsup=+\\infty$。","say":"有界的數列，s n 一定遞減又有下界，由單調收斂定理，這個極限一定存在。為什麼遞減？","t":[23832,33144]}],"check":1},{"title":"兩個好用的事實","beats":[{"show":["$\\limsup$ = 最大的子數列極限","$\\liminf$ = 最小的子數列極限"],"note":"完整證明在全文。","say":"實際計算靠這一條：上極限是所有子數列極限裡最大的，下極限是最小的。","t":[33144,40800]},{"show":["找出各子數列的極限，取最大與最小"],"say":"所以先把數列拆成幾個子數列，各自求極限，再挑最大和最小。","t":[40800,47352]},{"show":["$\\liminf a_n\\le\\limsup a_n$"],"note":"收斂 ⇔ 兩者相等（而且是實數）。","say":"下極限永遠不超過上極限。兩個相等而且是實數，數列就收斂，共同的值就是極限。","t":[47352,56736]}],"check":2},{"title":"每條尾巴都一樣","beats":[{"show":["$a_n=(-1)^n\\frac{n}{n+1}$"],"say":"看一個例子：正負交錯，大小是 n 加一分之 n。","t":[56736,61728]},{"show":["偶數項 $\\frac{2k}{2k+1}<1$，遞增 $\\to1$"],"note":"奇數項遞減 $\\to-1$。","say":"偶數項都比一小，一路往一爬；奇數項往負一走。","t":[61728,66984]},{"show":["任何 $n$ 之後都還有偶數項"],"say":"不管從第幾項切下尾巴，後面都還有偶數項，而且要多靠近一就有多靠近。","t":[66984,74328]}],"predict":{"ask":"尾巴的上確界 $s_n$ 是多少？","options":[{"label":"對每個 $n$ 都是 1","correct":true},{"label":"越來越小，最後趨近 1","why":"每條尾巴裡的偶數項都任意靠近 1，又都小於 1，所以每個 $s_n$ 剛好就是 1，不會先大後小。"},{"label":"就是 $a_n$","why":"$s_n$ 是整條尾巴的上確界，不是第 $n$ 項；奇數的 $n$ 時 $a_n$ 是負的，差得遠。"}]}},{"title":"$\\sup$ 不是 $\\limsup$","beats":[{"show":["$\\limsup=1$，$\\liminf=-1$"],"note":"不相等：發散。上極限 1 不是任何一項。","say":"所以上極限是一，下極限是負一，不相等，數列發散。注意，沒有任何一項等於一。","t":[74328,83664]},{"show":["$a_n=(-1)^n+\\frac{1}{n}$","$0,\\frac{3}{2},-\\frac{2}{3},\\frac{5}{4},\\dots$"],"say":"回到開頭的數列。前幾項：零、二分之三、負三分之二、四分之五。","t":[83664,91800]},{"show":["$\\sup=a_2=\\frac{3}{2}$"],"note":"被前面某一項偶然拉高。","say":"上確界是第二項，二分之三。但它只是前面某一項偶然很大，往後再也不會超過一太多。","t":[91800,101040]}],"check":0},{"title":"根值判別","beats":[{"show":["$a_n=2^n$（$n$ 偶）、$3^n$（$n$ 奇）"],"note":"冪級數 $\\sum a_nx^n$ 的收斂半徑？","say":"上極限真正派上用場的地方：這個冪級數的係數，偶數項是二的 n 次方，奇數項是三的 n 次方。","t":[101040,110184]},{"show":["$|a_n|^{1/n}$：2, 3, 2, 3, …"],"note":"沒有極限，$\\lim$ 用不了。","say":"開 n 次方根，一下二、一下三，沒有極限。比值判別更糟，一下趨近無限大、一下趨近零。","t":[110184,120096]},{"show":["$\\frac{1}{R}=\\limsup|a_n|^{1/n}$"],"say":"收斂半徑完整的公式用的是上極限。子數列極限只有兩個，上極限是哪一個？","t":[120096,128520]}],"check":3}],"checks":[{"ask":"$a_n=(-1)^n+\\frac{1}{n}$。$\\limsup a_n$ 是？","options":[{"label":"1","correct":true},{"label":"$\\frac{3}{2}$","why":"那是 $\\sup$，被 $a_2$ 一項拉高。$\\limsup$ 看的是最後的上緣：偶數項 $1+\\frac{1}{n}\\to1$。"},{"label":"不存在，因為數列發散","why":"有界數列的 $\\limsup$ 一定存在（$s_n$ 遞減有下界）。發散只表示 $\\limsup\\ne\\liminf$。"}]},{"ask":"為什麼 $s_n=\\sup\\{a_k:k\\ge n\\}$ 是遞減的？","options":[{"label":"$n$ 變大時，取 $\\sup$ 的集合變小","correct":true},{"label":"因為 $a_n$ 遞減","why":"$a_n$ 不必遞減；$(-1)^n+\\frac{1}{n}$ 就上下跳。$s_n$ 遞減是因為集合 $\\{a_k:k\\ge n+1\\}\\subseteq\\{a_k:k\\ge n\\}$。"},{"label":"因為 $s_n$ 收斂","why":"倒果為因：是先有遞減且有下界，才由單調收斂定理得到收斂。"}]},{"ask":"有界數列 $(a_n)$ 收斂的充要條件是？","options":[{"label":"$\\limsup a_n=\\liminf a_n$","correct":true},{"label":"$\\limsup a_n$ 存在","why":"有界時 $\\limsup$ 永遠存在，$(-1)^n$ 也有 $\\limsup=1$。要上下兩個相等才收斂。"},{"label":"$\\sup=\\inf$","why":"$\\sup=\\inf$ 表示數列是常數，太強了；$\\frac{1}{n}$ 收斂但 $\\sup=1$、$\\inf=0$。"}]},{"ask":"$a_n=2^n$（$n$ 偶）、$3^n$（$n$ 奇），$\\limsup|a_n|^{1/n}$ 是？","options":[{"label":"3","correct":true},{"label":"2","why":"那是 $\\liminf$。$\\limsup$ 取最大的子數列極限，奇數項給 3。"},{"label":"$\\frac{5}{2}$","why":"$\\limsup$ 不是把兩個子數列極限平均；它是最大的那一個。"}]}],"practice":[{"id":"an-ls-001","core":true},{"id":"an-ls-002","core":true},{"id":"an-ls-004","core":true},{"id":"an-sup-002","note":"對照：這題問的是 $\\inf$（含前面的項），不是 $\\liminf$。"},{"id":"an-ls-003","challenge":true,"note":"挑戰：$\\sin n$ 的子數列極限填滿 $[-1,1]$（因為 $\\pi$ 是無理數），$\\limsup=1$。"}]}});
